def home_today_tab(history, soil_type, hoja_threshold):
    """Panel de inicio: reúne lo urgente de toda la finca (carpocapsa, fungicidas,
    clima) para saber QUÉ HACER HOY sin entrar item por item. Solo resume; el
    detalle y las acciones están en cada item."""
    st.subheader("🏠 Panel de hoy")
    _hoy = pd.Timestamp.today()
    _dias = ["lunes", "martes", "miércoles", "jueves", "viernes", "sábado", "domingo"]
    st.caption(f"Lo urgente de toda la finca de un vistazo · {_dias[_hoy.weekday()]} "
               f"{_hoy.strftime('%d/%m/%Y')}. El detalle y las acciones, en cada item.")

    traps = st.session_state.get("carpocapsa_traps_df", pd.DataFrame())
    activities = st.session_state.get("activities_df", pd.DataFrame())

    # ── Carpocapsa ────────────────────────────────────────────────────────────
    # Mismos umbrales que el item Carpocapsa (si el usuario los cambió) para que
    # los dos paneles coincidan.
    try:
        cw = carpocapsa_build_multi_windows(
            traps, history, activities_df=activities, campaign_year=_hoy.year,
            capture_threshold=int(st.session_state.get("carp_capture_threshold", 3)),
            dd_active_start=int(st.session_state.get("carp_dd_start", 80)),
            dd_active_end=int(st.session_state.get("carp_dd_end", 130)),
        )
    except Exception:
        cw = pd.DataFrame()
    carpo_peligro = carpo_activa = pd.DataFrame()
    if not cw.empty and "Estado" in cw.columns:
        _est = cw["Estado"].astype(str)
        carpo_peligro = cw[_est.str.contains("cierra en", na=False)]
        carpo_activa = cw[_est.str.contains("Activa", na=False)
                          & ~_est.str.contains("cierra en", na=False)]

    # ── Fungicidas ────────────────────────────────────────────────────────────
    # Usa el MISMO pronóstico (forecast) que el item Decisiones; con forecast
    # vacío no se detectaban las "infecciones previstas" y salía 0 (incoherente).
    try:
        _forecast = st.session_state.get("forecast_df", pd.DataFrame())
        _persist = int(st.session_state.get("dec_persist_days", 16))
        _risk = build_risk_timeline(history, _forecast, days_back=60)
        dec = daily_treatment_decision(history, activities, _risk, persistence_days=_persist)
    except Exception:
        dec = pd.DataFrame()
    fung_hoy = fung_pronto = fung_vigilar = pd.DataFrame()
    if not dec.empty and "_priority" in dec.columns:
        fung_hoy = dec[dec["_priority"] == 1]      # tratar hoy (infección prevista + sin cobertura)
        fung_pronto = dec[dec["_priority"] == 2]   # tratar pronto (exposición acumulada + sin cobertura)
        fung_vigilar = dec[dec["_priority"] == 3]  # vigilar (cubierto hoy pero infección prevista)

    # ── Resumen superior ──────────────────────────────────────────────────────
    m1, m2, m3, m4, m5 = st.columns(5)
    m1.metric("🔴 Carpo. ≤3d", len(carpo_peligro))
    m2.metric("🟠 Carpo. activas", len(carpo_activa))
    m3.metric("🔴 Fungicida HOY", len(fung_hoy))
    m4.metric("🟠 Fungicida pronto", len(fung_pronto))
    m5.metric("🟡 Fungicida vigilar", len(fung_vigilar))

    st.markdown("---")
    st.markdown("### 🐛 Carpocapsa")
    if cw.empty:
        st.caption("Sin ventanas. Carga las capturas en el item 🐛 Carpocapsa.")
    else:
        if not carpo_peligro.empty:
            st.error("🔴 **PELIGRO — cierran en ≤3 días SIN tratar (última oportunidad):** "
                     + ", ".join(carpo_peligro["Campo/Zona"].astype(str).unique()))
        if not carpo_activa.empty:
            st.warning("🟠 **Ventanas activas para tratar:** "
                       + ", ".join(carpo_activa["Campo/Zona"].astype(str).unique()))
        if carpo_peligro.empty and carpo_activa.empty:
            st.success("✅ Sin ventanas activas hoy.")

    st.markdown("### 🍎 Fungicidas")
    if dec.empty or "_priority" not in dec.columns:
        st.caption("Sin datos suficientes (carga clima y actuaciones de Agroptima).")
    else:
        if not fung_hoy.empty:
            st.error("🔴 **Tratar HOY (infección prevista):** "
                     + ", ".join(fung_hoy["Campo"].astype(str)))
        if not fung_pronto.empty:
            st.warning("🟠 **Tratar pronto (cobertura caducada):** "
                       + ", ".join(fung_pronto["Campo"].astype(str)))
        if not fung_vigilar.empty:
            st.info("🟡 **Vigilar (cubiertos hoy, pero con infección prevista — la "
                    "cobertura terminará pronto):** "
                    + ", ".join(fung_vigilar["Campo"].astype(str)))
        if fung_hoy.empty and fung_pronto.empty and fung_vigilar.empty:
            st.success("✅ Todos los campos con cobertura vigente y sin infección prevista.")

    st.markdown("### 🌦️ Clima (últimos 7 días)")
    if history is None or history.empty:
        st.caption("Sin histórico climático cargado.")
    else:
        _m = None
        try:
            _ini = (_hoy.normalize() - pd.Timedelta(days=6)).date()
            _fin = _hoy.normalize().date()
            _m, _txt, _a7, _p = build_weekly_executive_report(history, activities, _ini, _fin)
        except Exception:
            _m = None
        if _m:
            def _n(v, d=1, s=""):
                try:
                    return f"{float(v):.{d}f}{s}"
                except Exception:
                    return "—"
            cc1, cc2, cc3, cc4 = st.columns(4)
            cc1.metric("🌡️ Temp media", _n(_m.get("temp_mean"), 1, " °C"))
            cc2.metric("🌧️ Lluvia", _n(_m.get("rain_total"), 1, " mm"))
            cc3.metric("🍄 Moteado (ev.≥1)", int(_m.get("scab_events_ge1", 0)))
            cc4.metric("🟤 Monilia (ev.≥1)", int(_m.get("monilia_events_ge1", 0)))
        else:
            st.caption("Sin datos suficientes para el resumen de 7 días.")

    st.markdown("---")

    # ── Envío manual del informe (movido desde Decisiones) ───────────────────
    #    Encaja mejor aquí: Panel de hoy ES el resumen diario. El envío
    #    automático de cada mañana lo hace scripts/daily_report.py; esto es solo
    #    para mandarlo a mano si se quiere.
    history_df    = history
    traps_df      = traps
    activities_df = activities
    forecast_df   = st.session_state.get("forecast_df", pd.DataFrame())

    with st.expander("📲 Enviar informe a Telegram", expanded=False):
        if not telegram_is_configured():
            st.info(
                "Para activar el envío a Telegram, añade en **Secrets** de Streamlit:\n\n"
                "```toml\n"
                "TELEGRAM_BOT_TOKEN = \"tu_token_del_bot\"\n"
                "TELEGRAM_CHAT_ID = \"tu_chat_id\"\n"
                "```\n\n"
                "El **token** te lo da @BotFather al crear el bot. "
                "El **chat_id** lo descubres escribiendo un mensaje a tu bot y pulsando el botón de abajo."
            )
            try:
                _tok = str(st.secrets.get("TELEGRAM_BOT_TOKEN", "")).strip()
            except Exception:
                _tok = ""
            if _tok:
                if st.button("🔍 Descubrir mi chat_id", key="tg_discover"):
                    _chats = telegram_discover_chats()
                    if _chats:
                        st.success("Chats que han escrito al bot:")
                        for _cid, _nom in _chats.items():
                            st.code(f'TELEGRAM_CHAT_ID = "{_cid}"   # {_nom}')
                    else:
                        st.warning(
                            "No se detectó ningún chat. Escribe primero un mensaje a tu bot "
                            "en Telegram (por ejemplo «hola») y vuelve a pulsar."
                        )
        else:
            st.success("✅ Telegram configurado. La app puede enviar informes.")
            _vista = st.checkbox("Ver el informe antes de enviar", value=True, key="tg_preview")
            if _vista:
                _preview = build_daily_report_text(
                    history_df, traps_df, activities_df,
                    forecast_df=forecast_df,
                    persistence_days=st.session_state.get("dec_persist_days", 16),
                )
                # Mostrar como texto plano (quitar etiquetas HTML para la vista previa)
                import re as _re_tg
                _plain = _re_tg.sub(r"</?[^>]+>", "", _preview)
                st.text(_plain)
            if st.button("📤 Enviar informe ahora", type="primary", key="tg_send"):
                _msg = build_daily_report_text(
                    history_df, traps_df, activities_df,
                    forecast_df=forecast_df,
                    persistence_days=st.session_state.get("dec_persist_days", 16),
                )
                _ok, _detalle = telegram_send_message(_msg)
                if _ok:
                    st.success(f"✅ {_detalle}")
                else:
                    st.error(f"❌ {_detalle}")

    st.caption("Este panel **resume**; para ver el detalle y actuar, entra en el item "
               "correspondiente (Carpocapsa, Decisiones, Sanidad…).")


def dashboard_tab(history, soil_type, hoja_threshold):
    st.subheader("Dashboard general")

    if history.empty:
        st.info("Carga primero el histórico en la pestaña Importación.")
        return

    min_dt = history["fecha_hora"].min()
    max_dt = history["fecha_hora"].max()

    c1, c2, c3 = st.columns(3)
    c1.metric("Registros horarios", len(history))
    c2.metric("Desde", str(min_dt))
    c3.metric("Hasta", str(max_dt))

    st.download_button(
        "⬇️ Descargar histórico (CSV)",
        data=history.to_csv(index=False).encode("utf-8-sig"),
        file_name=f"historico_finca_gallinal_{pd.Timestamp.now():%Y%m%d}.csv",
        mime="text/csv",
        use_container_width=True,
        help="Histórico climático horario completo (incluye humectación de hoja). "
             "Para análisis externos o para pasar el dato actualizado.",
    )

    with st.expander("🔍 Calidad del dato", expanded=False):
        avail_global = availability_table(history, min_dt, max_dt)
        st.dataframe(avail_global, use_container_width=True)

    st.markdown("#### Resumen últimos 30 días")
    last_start = max_dt - pd.Timedelta(days=30)
    last_df = history[(history["fecha_hora"] >= last_start) & (history["fecha_hora"] <= max_dt)].copy()
    if not last_df.empty:
        last_df = add_risk_columns(last_df, hoja_humeda_threshold=hoja_threshold)
        last_summary = period_summary(last_df, soil_type, last_start, max_dt)
        # Tabla vertical: transponer para evitar el scroll horizontal
        _summary_v = last_summary.T.reset_index()
        _summary_v.columns = ["Indicador", "Valor"]
        st.dataframe(_summary_v, use_container_width=True, hide_index=True)


