# ── Config de goteo EDITABLE (override de IRRIGATION_ZONES, persistida en Supabase) ─────
# Lo normal es editar los valores en el CÓDIGO (IRRIGATION_ZONES). Pero el usuario puede
# corregir un dato desde la app (uso de emergencia): se guarda SOLO la fila cambiada y manda
# sobre el código. El resto de funciones usan irrigation_zones_effective() (código + overrides).
SUPABASE_IRRIGATION_CONFIG_FILE = "irrigation_config.parquet"
_IRR_CFG_NUM = ["Metros", "Dist. (m)", "Caudal (L/h)", "Árboles"]
# Esquema COMPLETO (interno y persistido). "Válvula base" = nombre de CÓDIGO = ancla estable
# que NUNCA cambia (une la fila con su origen). "Válvula" = nombre EFECTIVO (el que debe
# coincidir con el Excel de Agronic); el usuario puede renombrarlo (plan B si Agronic cambia
# los nombres) sin romper el emparejamiento ni duplicar filas. "Campo" está bloqueado.
_IRR_CFG_FULL = ["Válvula base", "Válvula", "Campo"] + _IRR_CFG_NUM
# Columnas que ve/edita el usuario (sin el ancla interna).
IRR_CFG_EDIT_COLS = ["Válvula", "Campo"] + _IRR_CFG_NUM


def normalize_irrigation_config_df(df):
    """Normaliza el DataFrame de OVERRIDES (esquema completo con ancla)."""
    out = df.copy() if isinstance(df, pd.DataFrame) else pd.DataFrame()
    for c in _IRR_CFG_FULL:
        if c not in out.columns:
            out[c] = "" if c in ("Válvula base", "Válvula", "Campo") else np.nan
    out = out[_IRR_CFG_FULL].copy()
    if not out.empty:
        for c in ("Válvula base", "Válvula", "Campo"):
            out[c] = out[c].astype(str).str.strip()
        for c in _IRR_CFG_NUM:
            out[c] = pd.to_numeric(out[c], errors="coerce")
        out = out[(out["Válvula base"] != "") & (out["Válvula base"] != "nan") & (out["Campo"] != "")]
    return out.reset_index(drop=True)


def irrigation_config_base_rows():
    """Aplana IRRIGATION_ZONES (valores del CÓDIGO). Válvula base == Válvula (sin renombrar)."""
    rows = []
    for valv, parts in IRRIGATION_ZONES.items():
        for p in parts:
            rows.append({"Válvula base": valv, "Válvula": valv, "Campo": str(p.get("campo", "")).strip(),
                         "Metros": float(p.get("metros") or 0),
                         "Dist. (m)": float(p.get("dist_m") or 0),
                         "Caudal (L/h)": float(p.get("caudal_lph") or 0),
                         "Árboles": float(p.get("arboles") or 0)})
    return normalize_irrigation_config_df(pd.DataFrame(rows))


def irrigation_config_effective_rows():
    """Base del código + overrides (mandan por el ancla 'Válvula base'+'Campo'). Mismo nº y
    orden de filas que la base (un override reemplaza su fila, no añade) → sin duplicados."""
    base = irrigation_config_base_rows()
    ov = normalize_irrigation_config_df(st.session_state.get("irrigation_config_df", pd.DataFrame()))
    if ov.empty:
        return base
    ovi = ov.set_index(["Válvula base", "Campo"])
    rows = []
    for _, r in base.iterrows():
        key = (r["Válvula base"], r["Campo"])
        if key in ovi.index:
            o = ovi.loc[key]
            if isinstance(o, pd.DataFrame):
                o = o.iloc[0]
            nv = str(o["Válvula"]).strip()
            row = {"Válvula base": r["Válvula base"],
                   "Válvula": nv if nv not in ("", "nan") else r["Válvula"], "Campo": r["Campo"]}
            for c in _IRR_CFG_NUM:
                row[c] = o[c] if pd.notna(o[c]) else r[c]
            rows.append(row)
        else:
            rows.append(r.to_dict())
    return normalize_irrigation_config_df(pd.DataFrame(rows))


def irrigation_config_diff(edited_df, base_df):
    """Compara el editor (por POSICIÓN, mismas filas/orden) con la base → guarda solo las filas
    cambiadas, anclándolas por 'Válvula base' (permite haber renombrado la 'Válvula')."""
    ed = edited_df.reset_index(drop=True)
    b = base_df.reset_index(drop=True)
    keep = []
    for i in range(min(len(b), len(ed))):
        er, br = ed.iloc[i], b.iloc[i]
        new_v = str(er.get("Válvula", "")).strip()
        changed = bool(new_v) and (new_v != str(br["Válvula"]).strip())
        for c in _IRR_CFG_NUM:
            ev = pd.to_numeric(er.get(c), errors="coerce")
            if pd.notna(ev) and abs(float(ev) - float(br[c])) > 1e-6:
                changed = True
        if changed:
            row = {"Válvula base": br["Válvula base"], "Campo": br["Campo"],
                   "Válvula": new_v or br["Válvula"]}
            for c in _IRR_CFG_NUM:
                _v = pd.to_numeric(er.get(c), errors="coerce")
                row[c] = float(_v) if pd.notna(_v) else float(br[c])
            keep.append(row)
    return normalize_irrigation_config_df(pd.DataFrame(keep))


def irrigation_zones_effective():
    """{válvula EFECTIVA: [partes]} con overrides aplicados — lo que usa el resto del código en
    vez de la constante IRRIGATION_ZONES (clave = nombre renombrado si lo hubo)."""
    out = {}
    for _, r in irrigation_config_effective_rows().iterrows():
        out.setdefault(r["Válvula"], []).append({
            "campo": r["Campo"], "metros": float(r["Metros"]),
            "dist_m": float(r["Dist. (m)"]), "caudal_lph": float(r["Caudal (L/h)"]),
            "arboles": float(r["Árboles"])})
    return out


def irrigation_config_storage_url():
    url, _ = get_supabase_credentials()
    return f"{url.rstrip('/')}/storage/v1/object/climate-snapshots/{SUPABASE_IRRIGATION_CONFIG_FILE}"


def load_irrigation_config_from_supabase():
    if not supabase_is_configured():
        return None, "Supabase no configurado."
    headers = supabase_headers(); headers.pop("Prefer", None)
    try:
        r = requests.get(irrigation_config_storage_url(), headers=headers, timeout=60)
    except Exception as e:
        return None, f"Error de conexión: {e}"
    if r.status_code != 200:
        return None, "Sin config de riego guardada."
    try:
        return pd.read_parquet(io.BytesIO(r.content), engine="pyarrow"), "Cargado."
    except Exception as e:
        return None, f"Error Parquet: {e}"


def upload_irrigation_config_to_supabase(df):
    if not supabase_is_configured():
        return False, "Supabase no configurado."
    out = normalize_irrigation_config_df(df if df is not None else pd.DataFrame())
    buf = io.BytesIO()
    out.to_parquet(buf, index=False, compression="snappy", engine="pyarrow")
    buf.seek(0)
    headers = supabase_headers()
    headers["Content-Type"] = "application/octet-stream"
    headers["x-upsert"] = "true"
    try:
        r = requests.post(irrigation_config_storage_url(), headers=headers, data=buf.getvalue(), timeout=60)
    except Exception as e:
        return False, f"Error de conexión: {e}"
    if r.status_code not in (200, 201):
        return False, f"Error {r.status_code}"
    return True, f"Guardado: {len(out)} override(s)."


def autosave_irrigation_config_to_supabase():
    if not supabase_is_configured():
        return
    try:
        upload_irrigation_config_to_supabase(st.session_state.get("irrigation_config_df", pd.DataFrame()))
    except Exception:
        pass


def _field_area_m2(campo):
    for fr in FIELDS_BASE_ROWS:
        if str(fr.get("Campo", "")).strip() == str(campo).strip():
            ha = pd.to_numeric(fr.get("Superficie ha"), errors="coerce")
            return float(ha) * 10000.0 if pd.notna(ha) else None
    return None


def field_irrigation_zones(campo):
    out = []
    for parts in irrigation_zones_effective().values():
        for p in parts:
            if str(p.get("campo", "")).strip() == str(campo).strip():
                out.append(p)
    return out


def drip_system_metrics(campo):
    """Agrega las zonas de riego de un campo (riegan EN SECUENCIA) → nº goteros, caudal
    total (L/h), pluviometría efectiva (mm/h) y minutos por mm. 1 mm = 1 L/m²."""
    zs = field_irrigation_zones(campo)
    area = _field_area_m2(campo)
    if not zs or not area or area <= 0:
        return None
    try:
        n_em = sum(float(z["metros"]) / float(z["dist_m"]) for z in zs)
        flow = sum(float(z["metros"]) / float(z["dist_m"]) * float(z["caudal_lph"]) for z in zs)
        metros = sum(float(z["metros"]) for z in zs)
        arboles = sum(float(z.get("arboles") or 0) for z in zs)
        zonas = len(zs)                          # subsectores secuenciales
        # Solo 1/zonas riega a la vez → el tiempo de reloj para 1 mm se multiplica por zonas.
        rate = flow / area / zonas
        return {"n_emitters": n_em, "flow_lph": flow, "app_rate_mmph": rate,
                "min_per_mm": (60.0 / rate if rate > 0 else None), "area_m2": area,
                "arboles": arboles, "zonas": zonas, "metros": metros}
    except Exception:
        return None


def _hhmm_to_min(t):
    """'01:05' o time/datetime → minutos."""
    try:
        if hasattr(t, "hour"):
            return int(t.hour) * 60 + int(t.minute)
        h, m = str(t).split(":")[:2]
        return int(h) * 60 + int(m)
    except Exception:
        return 0


def parse_agronic_excel(uploaded_file):
    """Parsea el Excel 'Historial de sectores' (Agronic/Vegga) → DataFrame (Campo, Fecha, mm).
    Mapea cada zona (columna Nombre) a su campo vía IRRIGATION_ZONES y convierte los minutos
    regados a mm sobre la superficie del campo. Ignora zonas no reconocidas."""
    rows = []
    _zones = irrigation_zones_effective()
    try:
        xls = pd.ExcelFile(uploaded_file)
    except Exception:
        return pd.DataFrame(columns=["Campo", "Fecha", "mm"])
    for sh in xls.sheet_names:
        try:
            df = pd.read_excel(xls, sheet_name=sh, header=None)
        except Exception:
            continue
        for _, r in df.iterrows():
            fecha = pd.to_datetime(r.iloc[0], errors="coerce") if len(r) > 0 else pd.NaT
            if pd.isna(fecha):
                continue
            nombre = str(r.iloc[3]).strip() if len(r) > 3 else ""
            parts = _zones.get(nombre)
            if not parts:
                continue
            mins = _hhmm_to_min(r.iloc[4]) if len(r) > 4 else 0
            if mins <= 0:
                continue
            for p in parts:                       # una válvula puede regar VARIOS campos
                area = _field_area_m2(p["campo"])
                if not area:
                    continue
                emit = float(p["metros"]) / float(p["dist_m"])
                vol_l = emit * float(p["caudal_lph"]) * mins / 60.0     # litros
                rows.append({"Campo": p["campo"], "Fecha": fecha.normalize(),
                             "mm": vol_l / area})
    if not rows:
        return pd.DataFrame(columns=["Campo", "Fecha", "mm"])
    out = (pd.DataFrame(rows).groupby(["Campo", "Fecha"], as_index=False)["mm"].sum())
    out["mm"] = out["mm"].round(2)
    return out


# ── Descarga automática desde VEGGA (API de Progrés/Agrónic) ──────────────────
# La web de VEGGA baja el "Historial de sectores" (mismo Excel que subimos a mano) con un GET
# a su API pasando un token Bearer (JWT de Azure B2C, caduca ~2 h). Cada CABEZAL (programador)
# es un device con (modelo, id). El token es COMÚN a los 3. Se replica ese GET.
