def render_active_ingredient_reference(key_suffix=""):
    """Desplegable de referencia: materia activa ↔ marcas comerciales (con buscador).
    Reutilizado en Decisiones y Sanidad para responder rápido «difenoconazol = ¿cuál?»."""
    with st.expander("📖 ¿Qué producto comercial es cada materia activa? (difenoconazol = Score, Ceremonia…)",
                     expanded=False):
        st.caption(
            "La app habla por **materia activa** (el principio que manda en eficacia, grupo FRAC y "
            "resistencias). Aquí tienes las **marcas comerciales** habituales de cada una en manzano. "
            "⚠️ Orientativo: la lista **oficial y al día** está en el **Registro de Productos "
            "Fitosanitarios del MAPA** — confirma siempre que la marca concreta esté **registrada en "
            "manzano** antes de comprar."
        )
        _q = st.text_input(
            "Buscar materia activa o marca (p. ej. «difenoconazol» o «Score»)",
            key=f"ai_search{key_suffix}").strip().lower()
        _rows = ACTIVE_INGREDIENT_BRANDS
        if _q:
            _rows = [r for r in _rows if _q in r["activa"].lower() or _q in r["marcas"].lower()
                     or _q in r["frac"].lower() or _q in r.get("accion", "").lower()]
        if not _rows:
            st.info("Sin coincidencias. Prueba con otra parte del nombre.")
            return
        st.caption(
            "**Acción:** *Sistémico* = se absorbe y se mueve (preventivo + curativo, resiste la "
            "lluvia una vez dentro) · *Penetrante* = entra en la hoja pero se mueve poco · "
            "*Contacto* = en superficie, solo preventivo, se lava con la lluvia. Es distinto del "
            "**Estado** (registro)."
        )
        _th  = "background:#1a2e1e;color:white;padding:7px 10px;font-weight:600;font-size:12.5px;text-align:left;white-space:nowrap;"
        _td  = "padding:6px 10px;border-bottom:1px solid #e8e8e8;font-size:12.5px;white-space:nowrap;"
        _tdw = "padding:6px 10px;border-bottom:1px solid #e8e8e8;font-size:12.5px;white-space:normal;min-width:240px;"
        _hdr = (f'<th style="{_th}">Materia activa (lo que dice la app)</th>'
                f'<th style="{_th}">FRAC</th><th style="{_th}">Acción</th>'
                f'<th style="{_th}">Marcas comerciales</th><th style="{_th}">Estado</th>')
        _body = ""
        for _r in _rows:
            _body += (f'<tr><td style="{_td}"><b>{_r["activa"]}</b></td>'
                      f'<td style="{_td}">{_r["frac"]}</td>'
                      f'<td style="{_td}">{_r.get("accion", "—")}</td>'
                      f'<td style="{_tdw}">{_r["marcas"]}</td>'
                      f'<td style="{_td}">{_r["estado"]}</td></tr>')
        st.markdown(
            f'<div style="overflow-x:auto;border-radius:8px;border:1px solid #ddd;margin-top:0.3rem;">'
            f'<table style="border-collapse:collapse;width:100%;">'
            f'<thead><tr>{_hdr}</tr></thead><tbody>{_body}</tbody></table></div>',
            unsafe_allow_html=True,
        )


def build_rotation_advice(activities_df, catalog_df=None):
    """Analiza los FUNGICIDAS usados esta campaña (presión por grupo FRAC) y RANKEA
    toda la paleta de candidatos de mejor a peor para la próxima campaña, con el porqué.
    Devuelve: used_products, group_pressure {frac:pases}, used_fracs, ranked, warnings."""
    used_products  = {}
    group_pressure = {}   # frac (numérico) → nº de pases de esa campaña

    if activities_df is not None and not activities_df.empty and "Producto" in activities_df.columns:
        year = pd.Timestamp.now().year
        acts = activities_df.copy()
        acts["_dt"] = pd.to_datetime(acts.get("Fecha", pd.Series(dtype=str)), errors="coerce")
        acts = acts[acts["_dt"].dt.year == year]
        for _, r in acts.iterrows():
            # SOLO fungicidas: fuera insecticidas (Bactur, Decis), aceites (Laincoil), etc.
            if not is_fungicide_activity(r.get("Producto", ""), r.get("Trabajo", "")):
                continue
            prod = str(r.get("Producto", "")).strip()
            if not prod or prod.lower() == "nan":
                continue
            used_products[prod] = used_products.get(prod, 0) + 1
            _pl = prod.lower()
            for _al, _fr in _USED_FRAC_MAP:
                if any(a in _pl for a in _al):
                    for f in _fr:
                        group_pressure[f] = group_pressure.get(f, 0) + 1
                    break

    used_fracs = set(group_pressure.keys())

    # Ranking de la paleta: cuanto MENOS usado esté su grupo esta campaña, mejor; los
    # multisitios (M) suman por no generar resistencia. Cada uno con su explicación.
    # ¿Usado esta campaña? = alguno de sus alias aparece en los fungicidas registrados
    # en Agroptima este año. Así "Usado 2026 = Sí" refleja SOLO lo que de verdad aplicaste,
    # no los productos nuevos que aún no has comprado.
    _used_lc = [k.lower() for k in used_products]

    def _is_used(cand):
        return any(a in _k for a in cand["aliases"] for _k in _used_lc)

    ranked = []
    for c in ROTATION_CANDIDATES:
        min_p = min((group_pressure.get(f, 0) for f in c["fracs"]), default=0)
        score = max(0, 20 - min_p) + (8 if c["multisitio"] else 0)
        usado = _is_used(c)
        fresh = [f for f in c["fracs"] if group_pressure.get(f, 0) == 0]
        low   = [f for f in c["fracs"] if 0 < group_pressure.get(f, 0) <= 5]
        reasons = []
        if fresh:
            reasons.append(f"grupo {'+'.join(fresh)} SIN usar esta campaña")
        elif low:
            reasons.append(f"grupo {'+'.join(low)} poco usado")
        else:
            reasons.append(f"grupo {'+'.join(c['fracs'])} ya muy cargado — baja prioridad")
        if c["multisitio"]:
            reasons.append("multisitio: sin riesgo de resistencia")
        reasons.append("ya usado esta campaña" if usado else "aún no comprado")
        _ef = c["efic"]
        ranked.append({
            "Producto": c["nombre"],
            "FRAC": "+".join(c["fracs"]),
            "Moteado": f"{_ef.get('Moteado', 0)}%",
            "Monilia": f"{_ef.get('Monilia', 0)}%",
            "Oídio":   f"{_ef.get('Oídio', 0)}%",
            "Acción":  c["modo"],
            "Usado 2026": "Sí" if usado else "No",
            "Por qué (mejor→peor)": " · ".join(reasons),
            "_score": score,
        })
    ranked.sort(key=lambda x: (-x["_score"], x["Producto"]))

    # Avisos de sobrepresión: grupos de riesgo (3/7/11) muy por encima del límite FRAC.
    warnings = []
    for f, n in sorted(group_pressure.items(), key=lambda x: -x[1]):
        if f in ("3", "7", "11") and n > 4:
            warnings.append(
                f"⚠️ Grupo {f} ({_FRAC_NAMES.get(f, f)}) usado **{n} pases** esta campaña — "
                f"muy por encima del máximo FRAC (~4). Prioriza rotar FUERA del grupo {f}.")

    return {
        "used_products":  used_products,
        "group_pressure": group_pressure,
        "used_fracs":     used_fracs,
        "ranked":         ranked,
        "warnings":       warnings,
    }


