def is_fungicide_activity(producto_str, trabajo_str=""):
    """
    Devuelve True si una actuación de Agroptima es un tratamiento fungicida.

    Lógica de decisión (conservadora: si hay duda, NO es fungicida):
    1. Construye un texto combinado con producto + tipo de trabajo.
    2. Si contiene alguna keyword NON_FUNGICIDE y ninguna FUNGICIDE → False.
    3. Si contiene alguna keyword FUNGICIDE → True.
    4. Si el campo 'Trabajo' menciona explícitamente "fungicida" → True.
    5. En caso de duda (texto vacío o no clasificable) → False (conservador).
    """
    texto = (str(producto_str) + " " + str(trabajo_str)).lower()

    tiene_fungicida    = any(kw in texto for kw in _FUNGICIDE_KEYWORDS)
    tiene_no_fungicida = any(kw in texto for kw in _NON_FUNGICIDE_KEYWORDS)

    if tiene_no_fungicida and not tiene_fungicida:
        return False   # claramente no es fungicida
    if tiene_fungicida:
        return True    # confirmado fungicida
    # texto ambiguo o vacío → conservador: no contamos como cobertura fungicida
    return False


def fenologia_modo_hoy(today=None):
    """Modo de tratamiento según la FASE fenológica de HOY (ventanas regionales):
       · 'preventivo' (brotación 1–20 abr + floración 21 abr–21 may): el disparador es
         la COBERTURA caducada; la previsión solo INFORMA (no dispara sola).
       · 'reactivo' (cuajado 22 may → maduración 20 oct): solo un EVENTO REAL ya
         producido dispara; la previsión solo avisa.
       · 'reposo' (resto): fuera de campaña fúngica.
    Devuelve (modo, etiqueta_fase)."""
    t = pd.Timestamp.now().normalize() if today is None else pd.Timestamp(today).normalize()
    md = (t.month, t.day)
    if (4, 1) <= md <= (4, 20):
        return "preventivo", "Brotación"
    if (4, 21) <= md <= (5, 21):
        return "preventivo", "Floración"
    if (5, 22) <= md <= (6, 15):
        return "reactivo", "Cuajado"
    if (6, 16) <= md <= (8, 31):
        return "reactivo", "Engorde"
    if (9, 1) <= md <= (10, 20):
        return "reactivo", "Maduración"
    return "reposo", "Reposo"


def current_open_wet_event(history_df, lookback_days=5, gap_hours=6):
    """Si AHORA hay un periodo de hoja mojada EN CURSO (o cerrado hace < gap_hours),
    devuelve (mills_provisional, monilia_provisional, True). El valor es PROVISIONAL:
    sube hasta que la hoja se seca y el evento cierra. Sirve para adelantar la alerta
    (no esperar a que escampe) y para mostrar el valor con asterisco mientras crece."""
    try:
        if history_df is None or history_df.empty or "humectacion_hoja" not in history_df.columns:
            return 0.0, 0.0, False
        h = history_df.copy()
        h["fecha_hora"] = pd.to_datetime(h["fecha_hora"], errors="coerce")
        h = h.dropna(subset=["fecha_hora"])
        if h.empty:
            return 0.0, 0.0, False
        _last_ts = h["fecha_hora"].max()
        h = h[h["fecha_hora"] >= _last_ts - pd.Timedelta(days=lookback_days)]
        ev = detect_leaf_wetness_events(h)
        if ev is None or ev.empty:
            return 0.0, 0.0, False
        last = ev.sort_values("Fin").iloc[-1]
        if pd.isna(last.get("Fin")):
            return 0.0, 0.0, False
        if (_last_ts - pd.Timestamp(last["Fin"])) <= pd.Timedelta(hours=gap_hours):
            _m = min(float(pd.to_numeric(last.get("Ratio moteado"), errors="coerce") or 0) * 100, 150.0)
            _o = min(float(pd.to_numeric(last.get("Ratio monilia"), errors="coerce") or 0) * 100, 100.0)
            return round(_m), round(_o), True
        return 0.0, 0.0, False
    except Exception:
        return 0.0, 0.0, False


def daily_treatment_decision(history_df, activities_df, risk_df, persistence_days=16):
    """Envoltorio: resuelve el catálogo de fungicidas desde `session_state` (única
    dependencia de estado que tenía esta función) y delega en la versión CACHEADA.
    Si editas el catálogo en la tabla, cambia su hash y se recalcula automáticamente."""
    return _daily_treatment_decision_cached(
        history_df, activities_df, risk_df, persistence_days,
        st.session_state.get("fungicide_catalog_df"))


@st.cache_data(ttl=900, max_entries=6, show_spinner=False)
def _daily_treatment_decision_cached(history_df, activities_df, risk_df, persistence_days,
                                     fung_df):
    """
    Para cada campo de la finca, calcula el estado de protección FUNGICIDA y
    la acción recomendada para hoy.
    Solo tiene en cuenta aplicaciones de fungicidas (filtradas con is_fungicide_activity).
    La persistencia de la protección es la del ÚLTIMO producto aplicado (del catálogo
    de fungicidas, columna 'Persistencia días'); `persistence_days` queda como respaldo
    cuando ese producto no está catalogado.

    CACHEADA (ttl 15 min): es el motor por campo que usan Decisiones y Sanidad — recorre
    los 68 campos filtrando actuaciones, y era lo más caro de ambos items. Solo depende
    del DÍA (`now().normalize()`) y del catálogo, que llega ya como argumento.
    """
    today = pd.Timestamp.now().normalize()
    rows  = []
    _modo, _fase_label = fenologia_modo_hoy(today)   # mismo criterio de fase para toda la finca

    # Mapa de persistencia por producto, desde el catálogo de fungicidas (el mismo
    # que normaliza los productos). Base = DEFAULT_FUNGICIDE_CATALOG; si la sesión
    # tiene la columna editada, la sobrescribe.
    _persist_map = {
        str(d["Producto"]).strip(): float(d["Persistencia días"])
        for d in DEFAULT_FUNGICIDE_CATALOG if d.get("Persistencia días")
    }
    # (fung_df llega ya como argumento desde el envoltorio, para poder cachear. OJO: el
    #  nombre NO puede empezar por "_" o Streamlit lo excluiría de la clave del caché y
    #  las ediciones del catálogo no surtirían efecto.)
    if isinstance(fung_df, pd.DataFrame) and "Persistencia días" in fung_df.columns:
        for _, _fr in fung_df.iterrows():
            try:
                _pp = str(_fr["Producto"]).strip()
                _pv = float(_fr["Persistencia días"])
                if _pp and _pv > 0:
                    _persist_map[_pp] = _pv
            except (TypeError, ValueError, KeyError):
                pass

    # Mapa de VENTANA CURATIVA por producto (días en que un fungicida aplicado DESPUÉS
    # del evento aún puede frenar la infección, según etiqueta/notas: Folicur ~72h,
    # Luna 96-120h, estróbilurinas/Signum poca). Mismo patrón que la persistencia.
    _curative_map = {
        str(d["Producto"]).strip(): float(d["Ventana curativa días"])
        for d in DEFAULT_FUNGICIDE_CATALOG if d.get("Ventana curativa días")
    }
    if isinstance(fung_df, pd.DataFrame) and "Ventana curativa días" in fung_df.columns:
        for _, _fr in fung_df.iterrows():
            try:
                _pp = str(_fr["Producto"]).strip()
                _cv = float(_fr["Ventana curativa días"])
                if _pp and _cv >= 0:
                    _curative_map[_pp] = _cv
            except (TypeError, ValueError, KeyError):
                pass

    # Eficacia por ENFERMEDAD de cada producto (para exigir que el fungicida sea VÁLIDO
    # contra esa enfermedad, no solo estar en ventana temporal). Fuente: el catálogo de
    # productos de la app (etiquetas/literatura, editable) → sin inventar. Umbral 50 % =
    # cobertura válida (p.ej. el cobre ~25 % en oídio NO cubre oídio; los sistémicos 55-86 %
    # sí). Producto no catalogado → 50 (neutro, no penaliza).
    _EFF_THRESHOLD = 50.0
    _eff_catalog = default_treatment_catalog_copy()

    def _prod_disease_eff(prod_key):
        _n = str(prod_key).lower()
        for _tk, _ti in _eff_catalog.items():
            if _tk.lower() in _n or any(_al in _n for _al in _ti.get("aliases", [])):
                _e = _ti.get("eficacia", {})
                return {"Moteado": float(_e.get("Moteado", 50)),
                        "Monilia": float(_e.get("Monilia", 50)),
                        "Oídio":   float(_e.get("Oídio", 50))}
        return {"Moteado": 50.0, "Monilia": 50.0, "Oídio": 50.0}

    # Pre-process activities: solo fungicidas, con fecha válida
    acts_clean = pd.DataFrame()
    if not activities_df.empty and "Campos reconocidos" in activities_df.columns:
        _acts = activities_df.copy()
        _acts["Fecha_dt"] = pd.to_datetime(_acts["Fecha"], errors="coerce")
        _acts = _acts.dropna(subset=["Fecha_dt"])
        # Filtrar SOLO fungicidas
        _mask_fung = _acts.apply(
            lambda r: is_fungicide_activity(
                r.get("Producto", ""),
                r.get("Trabajo", ""),
            ),
            axis=1,
        )
        acts_clean = _acts[_mask_fung].copy()

    def _evento_cubierto(ev_date, fung_passes, disease):
        """Un evento de `disease` está cubierto si ALGÚN pase lo tapa: (a) el producto es
        VÁLIDO contra esa enfermedad (eficacia ≥ umbral) Y (b) está en ventana — dentro de SU
        persistencia si fue ANTES (preventivo) o de SU curativa si fue DESPUÉS (rescate).
        `fung_passes` = lista de (fecha, persistencia, curativa, eficacia_por_enfermedad)."""
        for f, persist, curativa, eff in fung_passes:
            if float(eff.get(disease, 50.0)) < _EFF_THRESHOLD:
                continue                         # ese producto no vale para esta enfermedad
            if (f <= ev_date and (ev_date - f).days <= persist) or \
               (f >= ev_date and (f - ev_date).days <= curativa):
                return True
        return False

    # Evento de hoja mojada EN CURSO ahora mismo (de finca): adelanta la alerta sin
    # esperar a que la hoja se seque. Provisional = sube hasta que el evento cierra.
    _open_mills, _open_monilia, _open_abierto = current_open_wet_event(history_df)
    _open_event = _open_abierto and (_open_mills >= 100 or _open_monilia >= 100)

    for field_row in FIELDS_BASE_ROWS:
        campo      = field_row["Campo"]
        variedades = field_row.get("Variedades actuales", "")

        # ── Última pasada fungicida ───────────────────────────────────────────
        # Matching EXACTO de campo. Agrupa por fecha para recoger TODOS los
        # fungicidas aplicados ese día (e.g. FLINT + SIGNUM en el mismo caldo).
        # Los productos no-fungicidas (Bactur, Aracan…) se ignoraron al filtrar acts_clean.
        last_date       = None
        last_products   = []   # lista de todos los fungicidas de la última pasada
        last_product    = "Sin registro"   # representación legible para display
        # Cada pase del campo (campaña) con SU persistencia y SU curativa según el
        # producto aplicado ese día → para contar "Ev. sin cobertura" por etiqueta real.
        _field_fung_passes = []   # lista de (fecha_norm, persistencia, curativa)
        if not acts_clean.empty:
            mask = acts_clean["Campos reconocidos"].fillna("").apply(
                lambda x: _campo_exact_in_list(x, campo)
            )
            campo_acts_all = acts_clean[mask].sort_values("Fecha_dt", ascending=False)
            _cy_acts = campo_acts_all[
                campo_acts_all["Fecha_dt"].notna() &
                (campo_acts_all["Fecha_dt"].dt.year == today.year)
            ]
            for _fd, _grp in _cy_acts.groupby(_cy_acts["Fecha_dt"].dt.normalize()):
                _pers_day, _cur_day = [], []
                _eff_day = {"Moteado": 0.0, "Monilia": 0.0, "Oídio": 0.0}
                for _, _gr in _grp.iterrows():
                    for _ck in _normalize_product_to_catalog(_gr.get("Producto", "")):
                        if _ck in _persist_map:
                            _pers_day.append(_persist_map[_ck])
                        if _ck in _curative_map:
                            _cur_day.append(_curative_map[_ck])
                        _e = _prod_disease_eff(_ck)   # caldo mixto → manda el más eficaz
                        for _dis in _eff_day:
                            _eff_day[_dis] = max(_eff_day[_dis], _e[_dis])
                # Caldo mixto → manda el de mayor persistencia / mayor curativa. Si el
                # producto no está catalogado, respaldo: persistencia global y curativa 4.
                _p = max(_pers_day) if _pers_day else float(persistence_days)
                _c = max(_cur_day) if _cur_day else 4.0
                if all(v == 0.0 for v in _eff_day.values()):   # producto sin catalogar
                    _eff_day = {"Moteado": 50.0, "Monilia": 50.0, "Oídio": 50.0}
                _field_fung_passes.append((_fd, _p, _c, _eff_day))
            if not campo_acts_all.empty:
                last_date = campo_acts_all.iloc[0]["Fecha_dt"].normalize()
                # Todos los productos fungicidas del mismo día = misma pasada
                same_day = campo_acts_all[
                    campo_acts_all["Fecha_dt"].dt.normalize() == last_date
                ]
                # Normalizar cada fila al catálogo y recoger todos los productos únicos
                _prods_set = []
                _seen_keys = set()
                for _, _row in same_day.iterrows():
                    for _ck in _normalize_product_to_catalog(_row.get("Producto", "")):
                        if _ck not in _seen_keys:
                            _prods_set.append(_ck)
                            _seen_keys.add(_ck)
                    # También guardar nombre original para display cuando no está en catálogo
                    _raw = str(_row.get("Producto", "")).strip()
                    if _raw and not _normalize_product_to_catalog(_raw):
                        pass  # producto no catalogado → no se muestra en last_products
                last_products = _prods_set if _prods_set else [
                    str(same_day.iloc[0].get("Producto", "Sin especificar")).strip()
                ]
                last_product = " + ".join(last_products) if last_products else "Sin especificar"

        # ── Persistencia efectiva = la del producto MÁS persistente de la última
        # pasada (si caldo mixto, manda el de protección más larga). Respaldo: el
        # valor global `persistence_days` si ningún producto está catalogado. ──
        _persist_vals = [_persist_map[_pk] for _pk in last_products if _pk in _persist_map]
        eff_persistence = max(_persist_vals) if _persist_vals else float(persistence_days)

        days_since = (today - last_date).days if last_date is not None else 999

        # ── Lluvia y eventos desde el último tratamiento ──────────────────────
        rain_since          = 0.0
        _rain_hours         = 0     # nº de horas con lluvia desde el último tratamiento
        mills_events_since  = 0
        monilia_events_since = 0
        oidio_events_since  = 0
        eventos_infeccion_dias = 0   # DÍAS distintos con infección (moteado, monilia u oídio)
        _infection_dates_since = []  # fechas de esos días-evento (para "Ev. sin cobertura")
        _dates_by_disease = {"Moteado": [], "Monilia": [], "Oídio": []}
        max_mills_since     = 0.0
        max_monilia_since   = 0.0

        ref_date = last_date if last_date is not None else today - pd.Timedelta(days=eff_persistence)

        if not history_df.empty:
            h = history_df.copy()
            h["fecha_hora"] = pd.to_datetime(h["fecha_hora"])
            h_since = h[h["fecha_hora"] >= ref_date]
            _ll_since = pd.to_numeric(h_since["lluvia_mm"], errors="coerce").fillna(0)
            rain_since = round(float(_ll_since.sum()), 1)
            _rain_hours = int((_ll_since > 0).sum())   # horas con lluvia (duración)

        # ── Lavado por lluvia (fases 1+2) ─────────────────────────────────────
        # Un CONTACTO puro (ventana curativa 0) pierde cobertura con la lluvia caída
        # desde que se aplicó, por DOS vías (se toma la MÁS restrictiva):
        #  · mm totales: intacto <15 mm, decae 15→50 mm, lavado ≥50 mm.
        #  · DURACIÓN (horas de lluvia): intacto <15 h, decae 15→55 h, lavado ≥55 h —
        #    así un evento largo y suave (p. ej. 15 mm en 48 h) también lo erosiona,
        #    aunque los mm no asusten. (Umbrales calibrables.)
        # Los SISTÉMICOS/penetrantes con curativa, absorbidos, son a prueba de lluvia → NO.
        _last_curwins = [_curative_map.get(_pk) for _pk in last_products if _pk in _curative_map]
        _is_contact_pass = bool(_last_curwins) and max(_last_curwins) <= 0
        _posible_lavado = False
        _lav_txt = ""
        if _is_contact_pass and last_date is not None:
            _wf_mm = 1.0 if rain_since < 15 else (0.0 if rain_since >= 50 else 1.0 - (rain_since - 15.0) / 35.0)
            _wf_h  = 1.0 if _rain_hours < 15 else (0.0 if _rain_hours >= 55 else 1.0 - (_rain_hours - 15.0) / 40.0)
            _wf = min(_wf_mm, _wf_h)
            if _wf < 1.0:
                eff_persistence = round(eff_persistence * _wf, 1)
                _posible_lavado = True
                _lav_txt = (f"lluvia prolongada ({_rain_hours} h de lluvia)"
                            if _wf_h <= _wf_mm else f"{rain_since:.0f} mm de lluvia")

        if not risk_df.empty:
            hist_risk = risk_df[(risk_df["Fecha"] >= ref_date) & (~risk_df["Es_prediccion"])]
            _mills_d   = hist_risk["Mills_valor"].fillna(0)   >= 100
            _monilia_d = hist_risk["Monilia_valor"].fillna(0) >= 100
            _oidio_d   = hist_risk.get("Oidio_valor", pd.Series(0.0, index=hist_risk.index)).fillna(0) >= 100
            mills_events_since   = int(_mills_d.sum())
            monilia_events_since = int(_monilia_d.sum())
            oidio_events_since   = int(_oidio_d.sum())
            # Un día con varias enfermedades = UN día-evento (mismo periodo), no varios.
            _inf_mask = _mills_d | _monilia_d | _oidio_d
            eventos_infeccion_dias = int(_inf_mask.sum())
            _infection_dates_since = pd.to_datetime(
                hist_risk.loc[_inf_mask, "Fecha"]).dt.normalize().tolist()
            _dates_by_disease = {
                "Moteado": pd.to_datetime(hist_risk.loc[_mills_d, "Fecha"]).dt.normalize().tolist(),
                "Monilia": pd.to_datetime(hist_risk.loc[_monilia_d, "Fecha"]).dt.normalize().tolist(),
                "Oídio":   pd.to_datetime(hist_risk.loc[_oidio_d, "Fecha"]).dt.normalize().tolist(),
            }
            max_mills_since      = float(hist_risk["Mills_valor"].fillna(0).max())
            max_monilia_since    = float(hist_risk["Monilia_valor"].fillna(0).max())

        # Evento REAL en los últimos 4 días (VENTANA CURATIVA): solo mientras esté
        # abierta tiene sentido el aviso reactivo (después, tratar no rescata nada).
        recent_event = False
        recent_mills = recent_monilia = recent_oidio = False
        if not risk_df.empty:
            _rec = risk_df[(~risk_df["Es_prediccion"]) &
                           (risk_df["Fecha"] >= today - pd.Timedelta(days=4)) &
                           (risk_df["Fecha"] <= today)]
            if not _rec.empty:
                recent_mills   = bool((_rec["Mills_valor"].fillna(0) >= 100).any())
                recent_monilia = bool((_rec["Monilia_valor"].fillna(0) >= 100).any())
                recent_oidio   = bool((_rec.get("Oidio_valor", pd.Series(0.0, index=_rec.index)).fillna(0) >= 100).any())
                recent_event = recent_mills or recent_monilia or recent_oidio

        # De los eventos DESDE EL ÚLTIMO TRATAMIENTO (los mismos que cuenta "Eventos
        # infección"), cuántos quedaron SIN cobertura según el MISMO criterio de la app
        # (persistencia del producto + ventana curativa). Mismo reloj que "Eventos infección":
        # si tratas el día 1 y hay un evento el día 2 dentro de la persistencia → cubierto (0).
        # Por enfermedad: un día-evento queda SIN cobertura si el producto no la tapa (ventana)
        # o no es válido contra ESA enfermedad (eficacia < umbral). Se cuentan DÍAS distintos.
        _uncov_dates = set()
        for _dis, _dts in _dates_by_disease.items():
            for _d in _dts:
                if not _evento_cubierto(_d, _field_fung_passes, _dis):
                    _uncov_dates.add(pd.Timestamp(_d).normalize())
        eventos_sin_cobertura = len(_uncov_dates)

        # ── Previsión 3 días ──────────────────────────────────────────────────
        fc_mills_max   = 0.0
        fc_monilia_max = 0.0
        fc_oidio_max   = 0.0
        fc_rain        = 0.0
        if not risk_df.empty:
            fc = risk_df[
                risk_df["Es_prediccion"] &
                (risk_df["Fecha"] >= today) &
                (risk_df["Fecha"] <= today + pd.Timedelta(days=3))
            ]
            if not fc.empty:
                fc_mills_max   = float(fc["Mills_valor"].fillna(0).max())
                fc_monilia_max = float(fc["Monilia_valor"].fillna(0).max())
                fc_oidio_max   = float(fc.get("Oidio_valor", pd.Series(0.0, index=fc.index)).fillna(0).max())
                fc_rain        = float(fc["Lluvia"].fillna(0).sum())

        # ── Lógica de decisión ────────────────────────────────────────────────
        # Basada en EPPO PP1/5 (Venturia), CABI compendium y guías RIMpro:
        #
        # COBERTURA CADUCADA: criterio temporal + efecto lluvia acumulada
        #   - Más de `eff_persistence` días sin fungicida (la del producto aplicado), O
        #   - Más de 12 días Y lluvia acumulada ≥ 35 mm (lixivia el contacto preventivo)
        unprotected = (days_since >= eff_persistence) or (days_since >= 12 and rain_since >= 35)

        # PREVISIÓN DE INFECCIÓN (próximos 3 días) — el factor más urgente.
        # Si hay cobertura caducada + previsión → tratar ANTES de que llegue la lluvia.
        # Umbral de AVISO por enfermedad, distinto del umbral de infección REAL (100).
        # La previsión sobrestima, así que se le pide más listón — ver
        # FORECAST_WARN_THR_DEFAULTS. Moteado 140, monilia y oídio 100.
        fc_mills_event   = fc_mills_max   >= forecast_warn_threshold("mills")
        fc_monilia_event = fc_monilia_max >= forecast_warn_threshold("monilia")
        fc_oidio_event   = fc_oidio_max   >= forecast_warn_threshold("oidio")
        fc_rain_alert    = fc_rain >= 15           # ≥15 mm previstos (umbral lavado + infección)
        fc_alert = fc_mills_event or fc_monilia_event or fc_oidio_event or fc_rain_alert

        # EXPOSICIÓN ACUMULADA SIN COBERTURA: DÍAS con infección (moteado y/o monilia) desde
        # el último fungicida. Cada día-evento = período de infección completado (latencia
        # 9-21 días, Rühmer 1998). NO dispara "tratar hoy" por sí solo, pero aumenta la
        # urgencia de planificar. Umbral: ≥3 días-evento sin cobertura = exposición seria (no
        # hay número en la bibliografía pero es conservador para pepita en fase sensible).
        # Cuenta DÍAS distintos (igual que la columna "Eventos infección"): un día con las dos
        # enfermedades = 1, no 2 (mismo evento de mojada).
        accumulated_exposure = eventos_infeccion_dias >= 3

        # ── Prioridades SEGÚN FASE FENOLÓGICA ─────────────────────────────────
        # Mismo criterio para Decisiones y Sanidad. El peso cambia con la fase:
        _RED, _ORA, _YEL, _GRN = "#ffcdd2", "#ffe0b2", "#fff9c4", "#f1f8f1"

        if _modo == "reposo":
            # Fuera de campaña fúngica (invierno / tras cosecha): sin decisión.
            priority = 4; action = "🟢 Fuera de campaña"; row_bg = _GRN

        elif _modo == "preventivo":
            # BROTACIÓN/FLORACIÓN: el disparador es la COBERTURA caducada (mantener
            # escudo). La previsión NO dispara sola — solo aumenta urgencia o avisa.
            if unprotected and _open_event:
                priority = 1; action = "🔴 TRATAR HOY — infección EN CURSO sin cobertura"; row_bg = _RED
            elif unprotected and (fc_alert or accumulated_exposure):
                priority = 1; action = "🔴 TRATAR HOY — sin cobertura (riesgo a la vista)"; row_bg = _RED
            elif unprotected:
                priority = 2; action = "🟠 Tratar pronto — mantener escudo (preventivo)"; row_bg = _ORA
            elif _open_event or fc_alert:
                priority = 3; action = "🟡 Vigilar — infección en curso/prevista (cobertura activa)"; row_bg = _YEL
            else:
                priority = 4; action = "🟢 OK — protegido"; row_bg = _GRN

        else:
            # CUAJADO EN ADELANTE: REACTIVO. Dispara un evento EN CURSO ahora mismo, o
            # un evento real DENTRO DE LA VENTANA CURATIVA (≤4 días). Pasada la ventana
            # el aviso se autocaduca (tratar ya no rescata). La previsión solo avisa.
            if _open_event and unprotected:
                priority = 1; action = "🔴 TRATAR HOY — infección EN CURSO (gánale tiempo)"; row_bg = _RED
            elif recent_event and unprotected:
                priority = 1; action = "🔴 TRATAR HOY — evento real (ventana curativa abierta)"; row_bg = _RED
            elif recent_event or _open_event:
                priority = 3; action = "🟡 Vigilar — evento real (cobertura aún activa)"; row_bg = _YEL
            elif fc_alert:
                priority = 3; action = "🟡 Vigilar — previsión (sin evento real aún)"; row_bg = _YEL
            else:
                priority = 4; action = "🟢 OK — sin eventos recientes"; row_bg = _GRN

        # Riesgo dominante (para seleccionar producto)
        # Solo incluye patógenos con previsión activa o exposición acumulada relevante
        # Riesgo principal = lo ACCIONABLE HOY, ETIQUETANDO el origen: (real) = infección real
        # reciente (≤4 días, ventana curativa) · (prev.) = solo previsto (3 días) · (real+prev.)
        # = ambas. NO se listan enfermedades cuyos eventos ya pasaron su ventana (tratar hoy no
        # los rescata), aunque sumen en "Eventos infección". `dominant` (limpio, sin etiqueta)
        # alimenta la selección de producto; `_rp_parts` es solo para MOSTRAR.
        dominant = []
        _rp_parts = []
        for _dis, _rec_f, _fc_f in (("Moteado", recent_mills, fc_mills_event),
                                    ("Monilia", recent_monilia, fc_monilia_event),
                                    ("Oídio",   recent_oidio,   fc_oidio_event)):
            if _rec_f or _fc_f:
                dominant.append(_dis)
                _tag = "real+prev." if (_rec_f and _fc_f) else ("real" if _rec_f else "prev.")
                _rp_parts.append(f"{_dis} ({_tag})")
        if not dominant and unprotected:
            # Sin cobertura y sin evento reciente/previsto concreto → espectro amplio preventivo.
            dominant = ["Moteado", "Monilia"]
            _rp_parts = ["Moteado (sin cobertura)", "Monilia (sin cobertura)"]
        if not dominant:
            dominant = ["—"]
            _rp_parts = ["—"]
        _riesgo_principal = " · ".join(_rp_parts)

        # Conteo de aplicaciones en la campaña actual para este campo
        _app_counts, _sdhi_total = count_field_applications(
            activities_df, campo, year=today.year
        )
        # Resumen legible de pases: "Flint 1/2 · Folicur 0/3"
        _pases_parts = []
        for _pk, _pmax in PRODUCT_MAX_APPLICATIONS.items():
            _n = _app_counts.get(_pk, 0)
            _short = _pk.split()[0]   # "FOLICUR", "SIGNUM", "FLINT", "LUNA"
            _pases_parts.append(f"{_short} {_n}/{_pmax}")
        _pases_label = " · ".join(_pases_parts)

        # Texto descriptivo del último fungicida aplicado
        if last_date:
            _last_label = f"{last_date.strftime('%d/%m/%Y')} · {last_product}"
        else:
            _last_label = "⚠️ Sin fungicida registrado"

        # Narrativa explicativa del motivo de tratamiento
        _narrative = build_treatment_narrative(
            days_since         = days_since,
            rain_since         = rain_since,
            mills_events_since = mills_events_since,
            monilia_events_since = monilia_events_since,
            fc_mills_max       = fc_mills_max,
            fc_monilia_max     = fc_monilia_max,
            fc_rain            = fc_rain,
            last_product       = last_product,
            persistence_days   = eff_persistence,
            priority           = priority,
            last_date          = last_date,
            infeccion_activa   = bool(_open_event or recent_event),
        )

        # Aviso de lavado: contacto reciente + lluvia relevante (mm o duración) desde su aplicación.
        if _posible_lavado:
            _narrative = (
                f"⚠️ POSIBLE LAVADO: el último pase fue un CONTACTO y ha recibido {_lav_txt} "
                f"desde que se aplicó → su protección se ha reducido (persistencia efectiva "
                f"recortada). Renueva la cobertura — o pasa a un SISTÉMICO si ya hay infección "
                f"en curso (el contacto no rescata).\n\n" + _narrative)

        # Momento del tratamiento (mismo criterio que la narrativa `_curativa`): si hay
        # infección reciente/en curso o cobertura recién caducada con evento → CURATIVO
        # (solo sistémico rescata); si no → PREVENTIVO (vale contacto o sistémico).
        _curativa_moment = bool(_open_event or recent_event) or (
            eventos_infeccion_dias >= 1 and days_since >= eff_persistence
            and days_since <= eff_persistence + 4)
        _momento = ("⚕️ Curativo — solo sistémico" if _curativa_moment
                    else "🛡️ Preventivo — contacto o sistémico")

        rows.append({
            "Campo":              campo,
            "Momento":            _momento,
            "Variedades":         variedades,
            "Último fungicida":  _last_label,
            "Días sin trat.":    (days_since if days_since < 999 else "—"),
            "Días protección":   int(round(eff_persistence)),
            "Lluvia desde mm":   rain_since,
            "Eventos infección":  eventos_infeccion_dias,
            "Ev. sin cobertura":  eventos_sin_cobertura,
            "Previsión Mills":   int(fc_mills_max),
            "Lluvia prevista mm": round(fc_rain, 1),
            "Pases campaña":     _pases_label,
            "Riesgo principal":  _riesgo_principal,
            "Fase":              f"{_fase_label} ({_modo})",
            "🎯 Acción":         action,
            "📋 Motivo":         _narrative,
            "_priority":         priority,
            "_modo":             _modo,
            "_bg":               row_bg,
            "_days_sort":        days_since,
            "_last_product":     last_product,
            "_dominant_list":    dominant,
            "_app_counts":       _app_counts,
            "_sdhi_total":       _sdhi_total,
            "_curativa_moment":  bool(_curativa_moment),
            "_posible_lavado":   bool(_posible_lavado),
        })

    df = (pd.DataFrame(rows)
          .sort_values(["_priority", "_days_sort"], ascending=[True, False])
          .drop(columns=["_days_sort"])
          .reset_index(drop=True))
    return df


# ── Hoja mojada en la PREVISIÓN (Sencrop no la trae) ─────────────────────────
# Dos modelos seleccionables (interruptor en Decisiones):
#   · "legacy" → método clásico/respaldo: mojada si llueve o HR≥92 (binario).
#   · "rimpro" → estilo RIMpro: mojada si llueve, o HR≥rh_thr, o hay ROCÍO
#     (T − punto de rocío ≤ dew_depr), con un RETARDO de secado (sigue mojada hasta
#     dry_lag horas tras un periodo húmedo si HR≥rh_dry). Calibrable contra el
#     sensor real del histórico (humectacion_hoja).
# Valores CALIBRADOS contra el sensor de la finca (mejor F1: HR≥92 · rocío≤1,5 ·
# retardo 1 h). Son los predeterminados permanentes para que se apliquen siempre,
# sin tener que recalibrar ni reaplicar tras un reinicio.
LEAF_WETNESS_DEFAULTS = {"rh_thr": 92.0, "dew_depr": 1.5, "dry_lag": 1, "rh_dry": 80.0}


def _dew_point_c(temp_c, rh_pct):
    """Punto de rocío (°C) — fórmula de Magnus-Tetens."""
    t = pd.to_numeric(temp_c, errors="coerce")
    rh = pd.to_numeric(rh_pct, errors="coerce").clip(lower=1, upper=100)
    a, b = 17.625, 243.04
    gamma = np.log(rh / 100.0) + a * t / (b + t)
    return b * gamma / (a - gamma)


def estimate_leaf_wetness_minutes(df, params=None):
    """Minutos de hoja mojada por hora (0/60) estimados sin sensor (estilo RIMpro).
    df necesita temp_media, hr_media, lluvia_mm. Devuelve Series alineada al índice.
    VECTORIZADO (sin bucle por fila) para no saturar memoria al calibrar."""
    p = {**LEAF_WETNESS_DEFAULTS, **(params or {})}
    t  = pd.to_numeric(df.get("temp_media"), errors="coerce")
    rh = pd.to_numeric(df.get("hr_media"),   errors="coerce")
    ll = pd.to_numeric(df.get("lluvia_mm"),  errors="coerce").fillna(0)
    td = _dew_point_c(t, rh)
    base = ((ll > 0.1) | (rh >= p["rh_thr"]) | ((t - td) <= p["dew_depr"])).fillna(False).to_numpy()
    dry_ok = (rh.fillna(0) >= float(p["rh_dry"])).to_numpy()
    # Retardo de secado: extiende la humedad hasta dry_lag horas tras un periodo
    # húmedo, mientras la HR siga alta (dry_ok). Se hace en ≤dry_lag pasos vectorizados.
    wet = base.copy()
    active = base.copy()
    for _ in range(int(p["dry_lag"])):
        cand = np.zeros_like(wet)
        cand[1:] = active[:-1]          # la hora siguiente a una hora húmeda activa
        cand = cand & dry_ok & (~wet)   # solo si HR alta y no estaba ya húmeda
        if not cand.any():
            break
        wet |= cand
        active = cand                   # la frontera sigue extendiéndose un paso más
    return pd.Series(np.where(wet, 60.0, 0.0), index=df.index)


def _lw_model_params():
    """(modelo, params) del estimador de hoja mojada, desde session_state."""
    try:
        model = st.session_state.get("lw_forecast_model", "rimpro")
        params = st.session_state.get("lw_params", dict(LEAF_WETNESS_DEFAULTS))
    except Exception:
        model, params = "rimpro", dict(LEAF_WETNESS_DEFAULTS)
    return model, params


def mg_rain_disponible():
    """Lluvia diaria de MeteoGalicia: en vivo si responde y, si no, del ARCHIVO.

    Streamlit Cloud no puede consultar servizos.meteogalicia.gal — nos bloquea las
    IPs de centro de datos. El informe diario corre en GitHub Actions, que sí
    conecta, y archiva cada mañana la previsión de MG para los próximos días. Sin
    este fallback la mezcla de lluvia no se aplicaba NUNCA desde la app: pedía el
    dato en vivo, recibía vacío y se quedaba con Sencrop en silencio.
    Devuelve {Timestamp: mm}."""
    try:
        vivo, _ = meteosix_wrf_daily_rain_cached()
        if vivo:
            return {pd.Timestamp(k).normalize(): float(v) for k, v in vivo.items()
                    if v is not None and pd.notna(v)}
    except Exception:
        pass
    try:
        arch = load_forecast_archive()
        if arch is None or arch.empty or "pred_rain_mg" not in arch.columns:
            return {}
        a = arch.copy()
        a["_d"] = pd.to_datetime(a.get("target_date"), errors="coerce").dt.normalize()
        a["_h"] = pd.to_numeric(a.get("horizon"), errors="coerce").fillna(99)
        a["_v"] = pd.to_numeric(a["pred_rain_mg"], errors="coerce")
        a = a.dropna(subset=["_d", "_v"])
        # De cada día, la emisión más reciente (horizonte más corto disponible).
        a = a.sort_values("_h").drop_duplicates("_d", keep="first")
        return {pd.Timestamp(d): float(v) for d, v in zip(a["_d"], a["_v"])}
    except Exception:
        return {}


def forecast_merge_rain_mg(forecast_df, mg_rain, modo="max"):
    """Mete la lluvia diaria de MeteoGalicia en la previsión HORARIA de Sencrop.

    Motivo (ago-2026): sobre el archivo de fiabilidad, a Sencrop se le escapan
    **11 de 18** episodios de lluvia (39 % avisados) mientras MeteoGalicia acierta
    **7 de 9** (78 %). La muestra de MG es corta para certificarlo, pero la de
    Sencrop es de sobra para descartarlo. Y como la lluvia es la entrada más
    directa del estimador de hoja mojada, cada lluvia que se escapa es mojadura
    que no se estima y una infección que no se avisa.

    `modo`:
      · "max"    — se queda con el MAYOR de los dos por día (recomendado). Un
                   avisador no debe perder episodios: si cualquiera de las dos
                   fuentes ve lluvia, se cuenta.
      · "mg"     — manda MeteoGalicia siempre que cubra ese día.
      · "sencrop"— no toca nada (comportamiento anterior).

    ⚠️ ASUNCIÓN EXPLÍCITA del reparto horario: MG solo da el total del día. Si
    Sencrop ya reparte lluvia ese día, se **escala** su perfil horario hasta el
    total elegido, respetando a qué horas llueve. Si Sencrop da 0 y MG ve lluvia,
    no hay perfil que escalar: se reparte a partes iguales entre las **6 horas de
    mayor humedad relativa** del día, como aproximación de cuándo es más probable
    que llueva. Es una heurística, no un dato — pero para el estimador de mojadura
    lo que importa es que esas horas queden marcadas como húmedas, no el milímetro
    exacto de cada una.
    """
    if forecast_df is None or forecast_df.empty or not mg_rain or modo == "sencrop":
        return forecast_df
    try:
        f = forecast_df.copy()
        f["fecha_hora"] = pd.to_datetime(f["fecha_hora"], errors="coerce")
        f = f.dropna(subset=["fecha_hora"])
        if f.empty or "lluvia_mm" not in f.columns:
            return forecast_df
        f["lluvia_mm"] = pd.to_numeric(f["lluvia_mm"], errors="coerce").fillna(0.0)
        f["_d"] = f["fecha_hora"].dt.normalize()
        mg = {pd.Timestamp(k).normalize(): float(v) for k, v in mg_rain.items()
              if v is not None and pd.notna(v)}
        for d, idx in f.groupby("_d").groups.items():
            if d not in mg:
                continue                       # MG no cubre ese día → dejar Sencrop
            _mg, _sc = mg[d], float(f.loc[idx, "lluvia_mm"].sum())
            objetivo = max(_mg, _sc) if modo == "max" else _mg
            if abs(objetivo - _sc) < 0.05:
                continue                       # ya coinciden
            if _sc > 0.05:
                f.loc[idx, "lluvia_mm"] = f.loc[idx, "lluvia_mm"] * (objetivo / _sc)
            elif objetivo > 0.05:
                # Sin perfil horario que escalar: repartir en las 6 h más húmedas.
                _hr = pd.to_numeric(f.loc[idx, "hr_media"], errors="coerce")
                _top = _hr.nlargest(min(6, len(idx))).index if _hr.notna().any() else idx[:6]
                f.loc[_top, "lluvia_mm"] = objetivo / max(len(_top), 1)
        return f.drop(columns=["_d"])
    except Exception:
        return forecast_df


def calibrate_leaf_wetness(history, sensor_min_minutes=30):
    """Compara el estimador RIMpro con el sensor real (humectacion_hoja) del
    histórico sobre una rejilla de parámetros. Devuelve (DataFrame, mejores_params).
    Métrica: F1 sobre la clasificación horaria mojada/seca."""
    need = {"temp_media", "hr_media", "lluvia_mm", "humectacion_hoja"}
    if history is None or history.empty or not need.issubset(history.columns):
        return pd.DataFrame(), None
    h = history[["temp_media", "hr_media", "lluvia_mm", "humectacion_hoja"]].copy()
    h = h[pd.to_numeric(h["humectacion_hoja"], errors="coerce").notna()
          & pd.to_numeric(h["hr_media"], errors="coerce").notna()
          & pd.to_numeric(h["temp_media"], errors="coerce").notna()]
    if h.empty:
        return pd.DataFrame(), None
    # Tope de tamaño para no saturar la memoria de Streamlit Cloud (reinicia y echa
    # fuera). Si hay muchísimas horas, se muestrea de forma uniforme.
    _MAX_ROWS = 35000
    if len(h) > _MAX_ROWS:
        h = h.iloc[:: max(1, len(h) // _MAX_ROWS)].head(_MAX_ROWS)
    h = h.reset_index(drop=True)
    measured = (pd.to_numeric(h["humectacion_hoja"], errors="coerce").fillna(0) >= sensor_min_minutes).to_numpy()
    n = len(measured)
    rows = []
    # Rejilla AMPLIADA (ago-2026). La anterior llegaba solo a HR 92 y rocío 1,0, y el
    # óptimo salía justo en ese borde (HR≥92 · rocío≤1,5 · retardo 1) — señal de que el
    # verdadero óptimo caía fuera de lo que se buscaba. Con esos parámetros el estimador
    # daba 15.707 horas mojadas frente a las 8.554 del sensor: 1,84× de más, que es lo
    # que infla las falsas alarmas de moteado (precisión ~43 %). Se extiende hasta HR 96
    # y rocío 0,3 para llegar a la zona restrictiva de verdad.
    _n_med = int(measured.sum())
    for rh_thr in (87, 88, 90, 92, 93, 94, 95, 96):
        for dew in (0.3, 0.5, 0.75, 1.0, 1.5, 2.0):
            for lag in (0, 1, 2, 3):
                est = (estimate_leaf_wetness_minutes(
                    h, {"rh_thr": rh_thr, "dew_depr": dew, "dry_lag": lag}) >= 30).to_numpy()
                tp = int(np.sum(est & measured)); fp = int(np.sum(est & ~measured))
                fn = int(np.sum(~est & measured)); tn = int(np.sum(~est & ~measured))
                prec = tp / (tp + fp) if (tp + fp) else 0.0
                rec  = tp / (tp + fn) if (tp + fn) else 0.0
                f1   = (2 * prec * rec / (prec + rec)) if (prec + rec) else 0.0
                _est_h = int(est.sum())
                rows.append({"HR≥": rh_thr, "Rocío ≤": dew, "Retardo h": lag,
                             "Acierto %": round((tp + tn) / n * 100, 1),
                             "Precisión %": round(prec * 100, 1),
                             "Sensibilidad %": round(rec * 100, 1),
                             "F1": round(f1, 3),
                             "h estim.": _est_h, "h medidas": _n_med,
                             # Cuánto infla (o recorta) las horas del sensor. 1,00 = clava
                             # el total; >1 sobra mojadura; <1 se queda corto.
                             "Ratio h est./med.": (round(_est_h / _n_med, 2) if _n_med else np.nan)})
    res = pd.DataFrame(rows).sort_values("F1", ascending=False).reset_index(drop=True)
    best = None
    if not res.empty:
        r0 = res.iloc[0]
        best = {"rh_thr": float(r0["HR≥"]), "dew_depr": float(r0["Rocío ≤"]),
                "dry_lag": int(r0["Retardo h"]), "rh_dry": 80.0}
    return res, best


@st.cache_data(ttl=1800, max_entries=12, show_spinner=False)
def build_risk_timeline(history_df, forecast_df, days_back=45, base_temp=10.0, upper_temp=31.1,
                        window_start=None, window_end=None):
    """
    DataFrame diario con valores de riesgo para Moteado, Monilia, Oídio y DD Carpocapsa.
    Cubre los últimos `days_back` días reales + todos los días de predicción.

    MODELO POR EVENTOS (coherente con el item Sanidad): el moteado y la monilia se
    calculan a partir de EVENTOS CONTINUOS de hoja mojada (detect_leaf_wetness_events)
    y su ratio frente al umbral de Mills, NO de la suma diaria de horas húmedas (que
    sobreestimaba y pintaba casi todos los días como "grave"). Cada evento se asigna
    al día en que TERMINA (cuando se completa la infección).

    CACHEADA (ttl 30 min): se invoca ~13 veces por render con distintas ventanas y es
    de lo más caro de la app. Solo depende del DÍA (usa `now().normalize()`, no la hora),
    así que el resultado es estable dentro de la jornada; el ttl cubre el cambio de día
    y, si recargas datos, el hash del histórico cambia y se recalcula sola.

    Ventana: por defecto va anclada al presente (últimos `days_back` días + previsión).
    Si se pasan `window_start`/`window_end` (Timestamp/fecha), se construye en cambio
    sobre ESE tramo histórico cerrado — útil para revisar una campaña pasada (p. ej.
    brotación→cosecha de 2024) solo con datos reales.
    """
    today = pd.Timestamp.now().normalize()
    _win = (window_start is not None) or (window_end is not None)
    start = pd.Timestamp(window_start).normalize() if window_start is not None else today - pd.Timedelta(days=int(days_back))
    # Fin (exclusivo) del tramo real: el día siguiente a window_end para incluirlo entero,
    # o "hoy" en el modo normal anclado al presente.
    _hist_end = (pd.Timestamp(window_end).normalize() + pd.Timedelta(days=1)) if window_end is not None else today

    # 1. Combinar histórico (real) + previsión (futuro) en un único horario.
    frames = []
    if history_df is not None and not history_df.empty:
        h = history_df.copy()
        h["fecha_hora"] = pd.to_datetime(h["fecha_hora"])
        h = h[(h["fecha_hora"] >= start) & (h["fecha_hora"] < _hist_end)].copy()
        if not h.empty:
            h["_es_pred"] = False
            frames.append(h)
    if forecast_df is not None and not forecast_df.empty:
        f = forecast_df.copy()
        f["fecha_hora"] = pd.to_datetime(f["fecha_hora"])
        f = f[f["fecha_hora"] >= today].copy()
        if _win:
            f = f[f["fecha_hora"] < _hist_end]
        if not f.empty:
            # La previsión no tiene sensor de hoja: se estima. Modelo seleccionable.
            if "humectacion_hoja" not in f.columns:
                f["humectacion_hoja"] = np.nan
            _sin_sensor = pd.to_numeric(f["humectacion_hoja"], errors="coerce").isna()
            _model, _params = _lw_model_params()
            if _model == "legacy":
                # Respaldo clásico: mojada si llueve o HR≥92 (binario).
                _hr = pd.to_numeric(f.get("hr_media"), errors="coerce")
                _ll = pd.to_numeric(f.get("lluvia_mm"), errors="coerce").fillna(0)
                _wet_min = np.where(((_hr >= 92) | (_ll > 0.1)), 60.0, 0.0)
            else:
                # RIMpro: lluvia / HR / rocío + retardo de secado (calibrable).
                _wet_min = estimate_leaf_wetness_minutes(f, _params).to_numpy()
            f.loc[_sin_sensor, "humectacion_hoja"] = np.asarray(_wet_min)[_sin_sensor.to_numpy()]
            f["_es_pred"] = True
            frames.append(f)

    if not frames:
        return pd.DataFrame()

    allh = pd.concat(frames, ignore_index=True).sort_values("fecha_hora")
    for _col in ("temp_media", "temp_min", "temp_max", "hr_media", "lluvia_mm", "humectacion_hoja"):
        if _col not in allh.columns:
            allh[_col] = np.nan

    # 2. Detectar eventos de hoja mojada sobre TODO el horario (igual que Sanidad)
    #    y mapear cada evento al día en que termina → máximo ratio de ese día.
    mills_by_day, monilia_by_day = {}, {}
    mills_evt_by_day, monilia_evt_by_day = {}, {}   # texto del periodo de mojada que dio el valor

    def _evt_txt(ini, fin, wet_eq):
        """Describe el periodo continuo de mojada que produjo el valor de ese día,
        listo para concatenar en el tooltip (vacío si no hay evento)."""
        try:
            if pd.isna(ini) or pd.isna(fin):
                return ""
            _h = f" · {float(wet_eq):.0f} h mojadas" if pd.notna(wet_eq) else ""
            return f"<br>🍃 Mojada continua: {ini:%d/%m %Hh} → {fin:%d/%m %Hh}{_h}"
        except Exception:
            return ""

    try:
        events = detect_leaf_wetness_events(allh)
    except Exception:
        events = pd.DataFrame()
    if events is not None and not events.empty:
        for _, ev in events.iterrows():
            fin = pd.to_datetime(ev.get("Fin"), errors="coerce")
            if pd.isna(fin):
                continue
            ini = pd.to_datetime(ev.get("Inicio"), errors="coerce")
            # EL RIESGO MARCA TODOS LOS DÍAS QUE LA HOJA ESTUVO MOJADA, no solo aquel en
            # que se secó. Antes se apuntaba únicamente al día del `Fin` del evento, y
            # eso dejaba el aviso SIEMPRE UN DÍA TARDE cuando la mojadura cruzaba la
            # medianoche: la noche del 27 al 28 de agosto de 2026 daba riesgo 0 el 27
            # —con 18 h de hoja mojada y lluvia— y 150 el 28, ya con la infección hecha.
            # Para un avisador eso es inútil: el aviso tiene que llegar mientras aún se
            # puede tratar. Agronómicamente también es lo correcto: si la hoja estuvo
            # mojada los dos días, los dos días hubo riesgo.
            # Cada día se queda con el valor MÁXIMO de los eventos que lo tocan.
            try:
                _dias = (pd.date_range(ini.normalize(), fin.normalize(), freq="D")
                         if pd.notna(ini) else [fin.normalize()])
            except Exception:
                _dias = [fin.normalize()]
            wet_eq = pd.to_numeric(ev.get("Horas húmedas equivalentes"), errors="coerce")
            rm = ev.get("Ratio moteado", np.nan)
            ro = ev.get("Ratio monilia", np.nan)
            _multi = len(_dias) > 1
            for d in _dias:
                _txt = _evt_txt(ini, fin, wet_eq)
                if _multi and _txt:
                    _txt += " (evento de varios días)"
                if pd.notna(rm):
                    _v = float(rm) * 100.0
                    if _v >= mills_by_day.get(d, -1.0):   # quedarse con el evento del valor máx.
                        mills_by_day[d] = _v
                        mills_evt_by_day[d] = _txt
                if pd.notna(ro):
                    _v = float(ro) * 100.0
                    if _v >= monilia_by_day.get(d, -1.0):
                        monilia_by_day[d] = _v
                        monilia_evt_by_day[d] = _txt

    # 3. Construir filas diarias con agregados meteo + valores de enfermedad por evento.
    allh["_fecha"] = allh["fecha_hora"].dt.date
    rows = []
    for fecha, g in allh.groupby("_fecha"):
        d = pd.Timestamp(fecha)
        es_pred  = bool(g["_es_pred"].any()) if "_es_pred" in g.columns else False
        temp_med = pd.to_numeric(g["temp_media"], errors="coerce").mean()
        temp_min = pd.to_numeric(g["temp_min"],   errors="coerce").min()
        temp_max = pd.to_numeric(g["temp_max"],   errors="coerce").max()
        hr_med   = pd.to_numeric(g["hr_media"],   errors="coerce").mean()
        lluvia   = pd.to_numeric(g["lluvia_mm"],  errors="coerce").sum()
        horas_hum = int((pd.to_numeric(g["humectacion_hoja"], errors="coerce").fillna(0) > 0).sum())
        dd_dia = max(0.0, min(float(temp_med) if pd.notna(temp_med) else 0.0, float(upper_temp)) - base_temp) if pd.notna(temp_med) else 0.0
        # Corrección de sesgo SOLO en días de predicción: el estimador de hoja mojada
        # infla las horas y el índice las hereda, así que el futuro pintaba picos que
        # luego no se cumplían. En los días reales la mojadura la mide el sensor y no
        # se toca nada. Ver FORECAST_BIAS_DEFAULTS.
        _bm = FORECAST_BIAS_DEFAULTS["mills"]   if es_pred else 1.0
        _bo = FORECAST_BIAS_DEFAULTS["monilia"] if es_pred else 1.0
        _bd = FORECAST_BIAS_DEFAULTS["oidio"]   if es_pred else 1.0
        rows.append({
            "Fecha":          d,
            "T_min":          round(float(temp_min), 1) if pd.notna(temp_min) else None,
            "T_max":          round(float(temp_max), 1) if pd.notna(temp_max) else None,
            "T_med":          round(float(temp_med), 1) if pd.notna(temp_med) else None,
            "HR_med":         round(float(hr_med), 1)   if pd.notna(hr_med)   else None,
            "Lluvia":         round(float(lluvia), 1)   if pd.notna(lluvia)   else 0.0,
            "Horas_mojadura": horas_hum,
            "Es_prediccion":  es_pred,
            "Mills_valor":    round(min(mills_by_day.get(d, 0.0) / _bm, 150.0), 1),
            "Mills_evento":   mills_evt_by_day.get(d, ""),
            "Monilia_valor":  round(min(monilia_by_day.get(d, 0.0) / _bo, 150.0), 1),  # techo 150 como Mills (severidad por encima del umbral 100, coherente con moteado)
            "Monilia_evento": monilia_evt_by_day.get(d, ""),
            "Oidio_valor":    round(_dec_oidio_value(temp_med, hr_med, lluvia) / _bd, 1),
            "DD_dia":         round(dd_dia, 1),
        })

    if not rows:
        return pd.DataFrame()

    df = pd.DataFrame(rows)
    df["Fecha"] = pd.to_datetime(df["Fecha"])
    df = df.drop_duplicates("Fecha", keep="last").sort_values("Fecha").reset_index(drop=True)
    df["DD_acumulado"] = df["DD_dia"].cumsum().round(1)
    return df


# ── Fiabilidad de la previsión: archiva el riesgo previsto y lo compara con lo
#    que de verdad pasó (confianza en el modelo para el triaje de parcelas). ──
# ── Windguru WRF 9 km: 2ª opinión de lluvia (lectura anónima del iapi público) ──────
# El WRF9 (id_model=21) es el modelo que el usuario lleva años viendo acertar en Trasona
# (spot 501097). No hay API oficial gratis para ESE modelo → se lee su iapi PÚBLICO de forma
# anónima (sin login), 1 vez/día, SOLO el dato gratuito (retraso ~6 h). Es una SEGUNDA columna
# de lluvia para comparar con Sencrop; si MeteoGalicia da la clave (API oficial), esa gana.
# Horizonte del WRF9 ≈ 3 días (modelo de corto plazo).
WINDGURU_SPOT_ID = "501097"       # Trasona (estación más cercana a la finca)
WINDGURU_WRF9_MODEL = 21          # "WRF 9 km (Europe)" en Windguru
WINDGURU_TZ_OFFSET_H = 2          # UTC+2 (verano Asturias) para agrupar la lluvia por día local


def windguru_wrf9_daily_rain(spot_id=WINDGURU_SPOT_ID, id_model=WINDGURU_WRF9_MODEL,
                             tz_offset_h=WINDGURU_TZ_OFFSET_H):
    """{fecha_normalizada: mm} de lluvia prevista por el WRF 9 km de Windguru (~3 días).
    Anónimo y a prueba de fallos: devuelve {} si algo va mal (→ columna vacía, sin drama)."""
    try:
        from collections import defaultdict
        from datetime import datetime, timezone, timedelta
        _h = {"User-Agent": ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                             "(KHTML, like Gecko) Chrome/126.0 Safari/537.36"),
              "Referer": f"https://www.windguru.cz/{spot_id}"}
        # 1) rundef ACTUAL del modelo (cambia con cada pasada)
        r1 = requests.get(f"https://www.windguru.cz/int/iapi.php?q=forecast_spot&id_spot={spot_id}",
                          headers=_h, timeout=30)
        if r1.status_code != 200:
            return {}

        def _find_run(o):
            if isinstance(o, dict):
                if o.get("id_model") == id_model and "rundef" in o:
                    return o.get("rundef"), o.get("cachefix", "")
                for v in o.values():
                    f = _find_run(v)
                    if f:
                        return f
            elif isinstance(o, list):
                for it in o:
                    f = _find_run(it)
                    if f:
                        return f
            return None

        _run = _find_run(r1.json())
        if not _run:
            return {}
        rundef, cachefix = _run
        # 2) forecast del WRF9 con ese rundef
        u = (f"https://www.windguru.net/int/iapi.php?q=forecast&id_model={id_model}"
             f"&rundef={rundef}&id_spot={spot_id}&WGCACHEABLE=21600&cachefix={cachefix}")
        r2 = requests.get(u, headers=_h, timeout=30)
        if r2.status_code != 200:
            return {}
        fc = r2.json().get("fcst", {})
        apcp, hours, init = fc.get("APCP1"), fc.get("hours"), fc.get("initstamp")
        if not apcp or not hours or init is None:
            return {}
        tz = timezone(timedelta(hours=tz_offset_h))
        daily = defaultdict(float)
        for _hh, _mm in zip(hours, apcp):
            if _mm is None:
                continue
            _ts = datetime.fromtimestamp(int(init) + int(_hh) * 3600, tz)
            daily[_ts.date()] += float(_mm)
        return {pd.Timestamp(d).normalize(): round(v, 1) for d, v in daily.items()}
    except Exception:
        return {}


@st.cache_data(ttl=3600, show_spinner=False)
def windguru_wrf9_daily_rain_cached():
    """Versión cacheada (1 h) para el panel — no golpear Windguru en cada rerun."""
    return windguru_wrf9_daily_rain()


# ── MeteoGalicia WRF (API oficial MeteoSIX): 3ª opinión de lluvia ──────────────────
# Fuente OFICIAL y gratuita (Xunta), consultada en el punto EXACTO de la finca y con
# malla de 1 km (9× más fina que el WRF9 de Windguru). Horizonte ~3,5 días. La API_KEY
# es un secreto (Streamlit secret / env var en headless) — NUNCA va en el código.
# Doc: getNumericForecastInfo, coords en orden lon,lat; variable precipitation_amount
# (l/m²=mm, horaria); modelo 'wrf'; malla 1km (probamos de fina a gruesa por si el punto
# cayera fuera de la más fina). Verificado 2026-07-20: la finca cae dentro de la de 1 km.
METEOSIX_URL    = "https://servizos.meteogalicia.gal/apiv5/getNumericForecastInfo"
METEOSIX_COORDS = "-5.7985,43.481583"   # lon,lat de El Gallinal (Serín, Gijón)


def _get_meteosix_key():
    """API_KEY de MeteoSIX desde el secret de Streamlit o la variable de entorno
    (informe diario headless en GitHub Actions). Nunca escrita en el código."""
    try:
        k = st.secrets.get("METEOSIX_API_KEY")
        if k:
            return str(k).strip()
    except Exception:
        pass
    import os as _os
    return (_os.environ.get("METEOSIX_API_KEY") or "").strip()


def meteosix_wrf_daily_rain_diag(coords=METEOSIX_COORDS, grids=("1km", "04km", "12km"),
                                 timeout=(5, 15)):
    """Igual que `meteosix_wrf_daily_rain` pero devuelve (datos, motivo_del_fallo).

    Antes la función se callaba ante CUALQUIER error (key ausente, HTTP 4xx/5xx,
    excepción de la API, red caída) y solo dejaba la columna vacía: imposible saber
    qué pasaba. Ahora el motivo se propaga para poder avisar en el panel.
    `motivo` = "" cuando todo fue bien.
    """
    key = _get_meteosix_key()
    if not key:
        return {}, "falta la API key (secret METEOSIX_API_KEY)"
    _ultimo = ""
    try:
        from collections import defaultdict
        for grid in grids:
            params = {"coords": coords, "variables": "precipitation_amount",
                      "models": "wrf", "grids": grid, "API_KEY": key}
            # timeout=(conectar, leer): 5 s para establecer conexión y 15 para la
            # respuesta. Antes eran 30 s únicos y, con el servidor de MeteoGalicia
            # caído (pasa: 2 veces en 4 días), la app se quedaba 30 s bloqueada al
            # abrir Decisiones. Si no conecta en 5 s, no va a conectar.
            r = requests.get(METEOSIX_URL, params=params, timeout=timeout)
            if r.status_code != 200:
                _ultimo = f"malla {grid}: HTTP {r.status_code}"
                continue
            js = r.json()
            if not isinstance(js, dict):
                _ultimo = f"malla {grid}: respuesta inesperada"
                continue
            if "exception" in js:
                # p. ej. el punto cae fuera de ESTA malla, o la key ya no vale (código 006)
                _e = js.get("exception") or {}
                _ultimo = f"malla {grid}: API {_e.get('code','?')} — {str(_e.get('message',''))[:110]}"
                continue
            daily = defaultdict(float)
            _horas = defaultdict(int)   # nº de horas sumadas por día (control de sanidad)
            _vistos = set()             # instantes ya contados → evita sumar dos veces
            got = False
            for feat in js.get("features", []):
                for day in feat.get("properties", {}).get("days", []):
                    for var in day.get("variables", []):
                        if var.get("name") != "precipitation_amount":
                            continue
                        for v in var.get("values", []):
                            _val, _ti = v.get("value"), v.get("timeInstant")
                            if _val is None or not _ti:
                                continue
                            # DEDUPLICAR por instante: la suma es acumulativa, así que si
                            # la respuesta repitiera una hora (dos pasadas del modelo, o
                            # solapamiento entre los bloques "days") el total del día se
                            # inflaría. Cada hora cuenta UNA vez.
                            if _ti in _vistos:
                                continue
                            _vistos.add(_ti)
                            # timeInstant ISO local ("...T11:00:00+02"): la fecha (10
                            # primeros caracteres) ya es el día LOCAL de la finca.
                            _d = pd.Timestamp(str(_ti)[:10])
                            daily[_d] += float(_val)
                            _horas[_d] += 1
                            got = True
            if got:
                # Control de sanidad: un día no puede tener más de 24 horas. Si pasa,
                # la respuesta traía series solapadas y el total no sería fiable.
                _raros = [d.strftime("%d/%m") for d, h in _horas.items() if h > 24]
                if _raros:
                    return {}, ("respuesta con horas duplicadas en " + ", ".join(_raros) +
                                " — total de lluvia no fiable, se descarta")
                return {pd.Timestamp(d).normalize(): round(v, 1) for d, v in daily.items()}, ""
            _ultimo = f"malla {grid}: sin valores de lluvia"
        return {}, (_ultimo or "sin datos")
    except Exception as _ex:
        # Traducir los fallos de red al castellano: el mensaje crudo de requests
        # ("ConnectTimeout: HTTPSConnectionPool(host=…)") no dice nada al usuario.
        _n = type(_ex).__name__
        if _n in ("ConnectTimeout", "ConnectionError", "NewConnectionError", "MaxRetryError"):
            return {}, ("el servidor de MeteoGalicia no responde (servicio caído o "
                        "inaccesible). No es tu API key: se reintenta solo más tarde")
        if "Timeout" in _n:
            return {}, "el servidor de MeteoGalicia tardó demasiado en responder"
        if _n == "SSLError":
            return {}, "fallo de certificado al conectar con MeteoGalicia"
        return {}, f"{_n}: {str(_ex)[:110]}"


# Variables de MeteoSIX → columnas canónicas de la app. Los tres vienen del MISMO
# endpoint que ya usábamos para la lluvia: no hay que aprender otra API.
METEOSIX_VARS = {
    "temperature":         "temp_media",
    "relative_humidity":   "hr_media",
    "precipitation_amount": "lluvia_mm",
}


def meteosix_wrf_hourly_diag(coords=METEOSIX_COORDS, grids=("1km", "04km", "12km")):
    """Serie **HORARIA** de temperatura, HR y lluvia del WRF de MeteoGalicia.

    `meteosix_wrf_daily_rain_diag` ya recibía valores hora a hora y los **sumaba** para
    dar el total del día: la serie horaria estaba ahí y se tiraba. Aquí se conserva, y
    se piden además temperatura y humedad, que son las entradas del modelo de infección.

    Para qué: la previsión archivada solo guarda ÍNDICES de riesgo (Mills, monilia), que
    se calculan pasando temperatura y HR por nuestro estimador de hoja mojada. Cuando un
    aviso falla no se puede saber si se equivocó la previsión o el estimador — y sabemos
    que el estimador da ~1,65× las horas que mide el sensor. Guardando temperatura y HR
    previstas se podrán comparar contra el sensor **sin el estimador de por medio**.

    Devuelve (DataFrame[fecha_hora, temp_media, hr_media, lluvia_mm], motivo_del_fallo).
    """
    key = _get_meteosix_key()
    if not key:
        return pd.DataFrame(), "falta la API key (secret METEOSIX_API_KEY)"
    _ultimo = ""
    # Se piden las tres variables juntas y, si no vuelve nada, se prueban DE UNA EN UNA.
    # Motivo: si un solo nombre de variable no le gusta a MeteoSIX, la petición entera
    # falla y nos quedamos sin ninguna — que es lo que pasó el 22/08/2026, cuando la
    # lluvia diaria (una sola variable) sí se archivó y la horaria no. Mejor quedarse con
    # dos de tres que con ninguna.
    _juegos = [list(METEOSIX_VARS)] + [[v] for v in METEOSIX_VARS]
    try:
        for grid in grids:
            _filas, _cols_ok, _errs = {}, set(), []
            for _vars in _juegos:
                # No repetir lo ya conseguido: si la petición conjunta funcionó, las
                # sueltas sobran; y si trajo dos de tres, solo se reintenta la que falta.
                _pend = [v for v in _vars if METEOSIX_VARS[v] not in _cols_ok]
                if not _pend:
                    continue
                # MeteoSIX exige **un modelo por cada variable**: pedir 3 variables con un
                # solo «wrf» da API 306 («the number of requested models is 1 and the
                # number of requested variables is 3, but they must be the same»). Por eso
                # la lluvia diaria funcionaba —una variable, un modelo— y esto no.
                params = {"coords": coords, "variables": ",".join(_pend),
                          "models": ",".join(["wrf"] * len(_pend)),
                          "grids": grid, "API_KEY": key}
                r = requests.get(METEOSIX_URL, params=params, timeout=(5, 20))
                if r.status_code != 200:
                    _errs.append(f"{'+'.join(_pend)}: HTTP {r.status_code}")
                    continue
                js = r.json()
                if not isinstance(js, dict):
                    _errs.append(f"{'+'.join(_pend)}: respuesta inesperada")
                    continue
                if "exception" in js:
                    _e = js.get("exception") or {}
                    _errs.append(f"{'+'.join(_pend)}: API {_e.get('code','?')} — "
                                 f"{str(_e.get('message',''))[:90]}")
                    continue
                for feat in js.get("features", []):
                    for day in feat.get("properties", {}).get("days", []):
                        for var in day.get("variables", []):
                            _col = METEOSIX_VARS.get(var.get("name"))
                            if not _col:
                                continue
                            for v in var.get("values", []):
                                _val, _ti = v.get("value"), v.get("timeInstant")
                                if _val is None or not _ti:
                                    continue
                                # timeInstant viene en hora LOCAL con offset ("…T11:00:00+02").
                                _ts = pd.to_datetime(_ti, errors="coerce")
                                if pd.isna(_ts):
                                    continue
                                try:
                                    _ts = _ts.tz_localize(None)
                                except Exception:
                                    pass
                                _filas.setdefault(_ts, {"fecha_hora": _ts})[_col] = float(_val)
                                _cols_ok.add(_col)
            if _filas:
                df = pd.DataFrame(list(_filas.values())).sort_values("fecha_hora")
                # Se avisa de lo que NO se pudo traer: es mejor archivar dos variables de
                # tres sabiéndolo que creer que están las tres.
                _falta = [c for c in METEOSIX_VARS.values() if c not in _cols_ok]
                _av = (f"sin {', '.join(_falta)} ({' · '.join(_errs[:3])})" if _falta else "")
                return df.reset_index(drop=True), _av
            _ultimo = f"malla {grid}: " + (" · ".join(_errs[:3]) if _errs else "sin valores")
        return pd.DataFrame(), (_ultimo or "sin datos")
    except Exception as _ex:
        _n = type(_ex).__name__
        if _n in ("ConnectTimeout", "ConnectionError", "NewConnectionError", "MaxRetryError"):
            return pd.DataFrame(), ("el servidor de MeteoGalicia no responde (servicio caído "
                                    "o inaccesible). No es tu API key")
        if "Timeout" in _n:
            return pd.DataFrame(), "el servidor de MeteoGalicia tardó demasiado en responder"
        return pd.DataFrame(), f"{_n}: {str(_ex)[:110]}"


def meteosix_wrf_daily_rain(coords=METEOSIX_COORDS, grids=("1km", "04km", "12km")):
    """{fecha_normalizada: mm} de lluvia prevista por el WRF de MeteoGalicia (~3,5 días,
    malla 1 km oficial en el punto exacto de la finca). Prueba mallas de fina a gruesa
    (si el punto cae fuera de la de 1 km, baja a 4 km, etc.). A prueba de fallos: devuelve
    {} si no hay key, hay error o el punto cae fuera de todo → columna vacía, sin drama."""
    return meteosix_wrf_daily_rain_diag(coords, grids)[0]


@st.cache_data(ttl=3600, show_spinner=False)
def meteosix_wrf_daily_rain_cached():
    """Versión cacheada (1 h) para el panel — no golpear la API en cada rerun.

    UNA sola malla y timeouts cortos a propósito: desde Streamlit Cloud esta llamada
    **nunca** funciona (MeteoGalicia bloquea las IPs de centro de datos) y el valor bueno
    llega igual del archivo que escribe el informe diario. Probar las tres mallas con
    timeout de 20 s costaba hasta un minuto de espera al abrir, para nada. El informe
    diario sí usa la versión completa, que es donde importa acertar la malla.
    Devuelve (datos, motivo) para poder mostrar por qué falla si viene vacío."""
    return meteosix_wrf_daily_rain_diag(grids=("1km",), timeout=(3, 6))


SUPABASE_FORECAST_ARCHIVE_PATH = "forecast_risk_archive.parquet"
def purge_mg_hourly_archive():
    """Vacía el archivo horario de MeteoGalicia (sobrescribe con un parquet vacío).

    Hace falta cuando lo acumulado se midió con un criterio que luego resultó estar mal
    —las primeras 89 horas se archivaron con el horizonte inflado 2 h, por comparar la
    hora UTC del servidor con las horas locales de MeteoSIX—. Mezclar esas con las
    buenas ensucia justo lo que se quiere medir: el acierto según la antelación."""
    if not supabase_is_configured():
        return False, "Supabase no está configurado."
    try:
        vacio = pd.DataFrame(columns=["issue_date", "target_dt", "horizon_h",
                                      "mg_temp", "mg_hr", "mg_rain"])
        buf = io.BytesIO()
        vacio.to_parquet(buf, index=False, compression="snappy", engine="pyarrow")
        buf.seek(0)
        endpoint = climate_snapshot_storage_url(SUPABASE_MG_HOURLY_PATH)
        headers = supabase_headers()
        headers["Content-Type"] = "application/octet-stream"
        headers["x-upsert"] = "true"
        r = requests.post(endpoint, headers=headers, data=buf.getvalue(), timeout=60)
        try:
            _descargar_mg_hourly.clear()
        except Exception:
            pass
        ok = r.status_code in (200, 201)
        return ok, ("Archivo horario de MeteoGalicia vaciado. Volverá a llenarse en la "
                    "próxima ejecución del informe diario." if ok
                    else f"No se pudo vaciar (HTTP {r.status_code}).")
    except Exception as e:
        return False, f"{type(e).__name__}: {str(e)[:120]}"


def archive_mg_hourly_forecast():
    """Guarda (1 vez al día) la previsión horaria de MeteoGalicia para poder medirla.

    Solo corre de verdad desde el informe diario: Streamlit Cloud no consigue conectar
    con MeteoGalicia (nos bloquean las IPs de centro de datos), así que desde la app
    esto no hace nada y no molesta.

    Se guarda **sin tocar nada de lo que se ve**: es únicamente recogida de datos, para
    poder decidir con hechos si MeteoGalicia puede sustituir a la previsión de Sencrop
    —que dejó de estar disponible el 19/08/2026— en vez de apostar. Con dos semanas se
    ve la tendencia; con un mes se decide.
    """
    try:
        if not supabase_is_configured():
            return False, "Supabase no configurado."
        # HORA LOCAL DE LA FINCA, no la del servidor. Esto corre en GitHub Actions, que va
        # en UTC: comparar contra `pd.Timestamp.now()` metía dos horas de error en verano
        # — se archivaban como «futuras» horas que ya habían pasado, y el horizonte salía
        # inflado en 2 h, con lo que las horas caían en el tramo de antelación equivocado.
        # Los timeInstant de MeteoSIX vienen en hora local, así que hay que compararlos
        # con hora local.
        try:
            _ahora = pd.Timestamp.now(tz="Europe/Madrid").tz_localize(None)
        except Exception:
            _ahora = pd.Timestamp.now()
        _hoy = _ahora.normalize()
        _issue = _hoy.strftime("%Y-%m-%d")
        df, err = meteosix_wrf_hourly_diag()
        if df is None or df.empty:
            return False, err or "sin datos de MeteoGalicia"
        d = df.copy()
        d["fecha_hora"] = pd.to_datetime(d["fecha_hora"], errors="coerce")
        d = d.dropna(subset=["fecha_hora"])
        # Fuera las horas ya pasadas: no son previsión, son el día en curso a medias.
        # Es el mismo error de horizonte 0 que falseó el archivo de riesgo en agosto.
        d = d[d["fecha_hora"] > _ahora]
        if d.empty:
            return False, "la previsión de MeteoGalicia no cubre ninguna hora futura"
        out = pd.DataFrame({
            "issue_date": _issue,
            "target_dt": d["fecha_hora"],
            "horizon_h": ((d["fecha_hora"] - _ahora).dt.total_seconds() // 3600).astype(int),
            "mg_temp": pd.to_numeric(d.get("temp_media"), errors="coerce"),
            "mg_hr": pd.to_numeric(d.get("hr_media"), errors="coerce"),
            "mg_rain": pd.to_numeric(d.get("lluvia_mm"), errors="coerce"),
        })
        old = load_mg_hourly_archive()
        if old is not None and not old.empty:
            out = pd.concat([old, out], ignore_index=True)
            out = out.drop_duplicates(subset=["issue_date", "target_dt"], keep="last")
        buf = io.BytesIO()
        out.to_parquet(buf, index=False, compression="snappy", engine="pyarrow")
        buf.seek(0)
        endpoint = climate_snapshot_storage_url(SUPABASE_MG_HOURLY_PATH)
        headers = supabase_headers()
        headers["Content-Type"] = "application/octet-stream"
        headers["x-upsert"] = "true"
        r = requests.post(endpoint, headers=headers, data=buf.getvalue(), timeout=60)
        try:                       # que el panel no siga viendo el archivo viejo
            _descargar_mg_hourly.clear()
        except Exception:
            pass
        if r.status_code in (200, 201):
            # El aviso de meteosix_wrf_hourly_diag se propaga: puede haber archivado bien
            # pero con una variable menos, y eso hay que verlo en el log del informe.
            return True, (f"{len(d)} horas archivadas (total {len(out)})."
                          + (f" ⚠️ {err}" if err else ""))
        return False, f"HTTP {r.status_code} al subir."
    except Exception as e:
        return False, f"{type(e).__name__}: {str(e)[:120]}"


def upload_forecast_archive(df):
    """Sube el archivo de previsiones (parquet) a Supabase Storage. Silencioso."""
    if not supabase_is_configured() or df is None or df.empty:
        return False
    try:
        buf = io.BytesIO()
        df.to_parquet(buf, index=False, compression="snappy", engine="pyarrow")
        buf.seek(0)
        endpoint = climate_snapshot_storage_url(SUPABASE_FORECAST_ARCHIVE_PATH)
        headers = supabase_headers()
        headers["Content-Type"] = "application/octet-stream"
        headers["x-upsert"] = "true"
        r = requests.post(endpoint, headers=headers, data=buf.getvalue(), timeout=60)
        return r.status_code in (200, 201)
    except Exception:
        return False


@st.cache_data(ttl=300, show_spinner=False)
def _download_forecast_archive(url, key, cache_buster=0):
    try:
        endpoint = (f"{url.rstrip('/')}/storage/v1/object/"
                    f"{SUPABASE_SNAPSHOT_BUCKET}/{SUPABASE_FORECAST_ARCHIVE_PATH}")
        r = requests.get(endpoint, headers={"apikey": key, "Authorization": f"Bearer {key}"},
                         timeout=60)
        return r.content if r.status_code == 200 else None
    except Exception:
        return None


def load_forecast_archive(use_cache=True):
    """Carga el histórico de previsiones archivadas (DataFrame) desde Supabase."""
    if not supabase_is_configured():
        return pd.DataFrame()
    try:
        url, key = get_supabase_credentials()
        if not use_cache:
            _download_forecast_archive.clear()
        content = _download_forecast_archive(url, key, 0 if use_cache else int(time.time()))
        if not content:
            return pd.DataFrame()
        return pd.read_parquet(io.BytesIO(content), engine="pyarrow")
    except Exception:
        return pd.DataFrame()


def purge_forecast_archive():
    """Reinicia el archivo de previsiones SOBRESCRIBIÉNDOLO con un parquet vacío (el
    DELETE de Storage da 400; el POST/upsert sí funciona). Limpia caché y el flag de
    sesión para volver a archivar la previsión de hoy enseguida."""
    if not supabase_is_configured():
        return False, "Supabase no está configurado."
    try:
        empty = pd.DataFrame(columns=["issue_date", "target_date", "horizon",
                                      "pred_mills", "pred_monilia", "pred_oidio", "pred_rain"])
        buf = io.BytesIO()
        empty.to_parquet(buf, index=False, compression="snappy", engine="pyarrow")
        buf.seek(0)
        endpoint = climate_snapshot_storage_url(SUPABASE_FORECAST_ARCHIVE_PATH)
        headers = supabase_headers()
        headers["Content-Type"] = "application/octet-stream"
        headers["x-upsert"] = "true"
        r = requests.post(endpoint, headers=headers, data=buf.getvalue(), timeout=60)
        ok = r.status_code in (200, 201)
        try:
            _download_forecast_archive.clear()
        except Exception:
            pass
        try:
            for _k in [k for k in st.session_state.keys() if str(k).startswith("_fc_archived_")]:
                del st.session_state[_k]
        except Exception:
            pass
        return ok, (f"Archivo reiniciado (HTTP {r.status_code})." if ok
                    else f"No se pudo reiniciar (HTTP {r.status_code}).")
    except Exception as e:
        return False, str(e)


def archive_today_forecast(history_df, forecast_df):
    """Guarda (UNA vez al día) el riesgo PREVISTO por día — Sencrop (moteado/monilia/oídio/
    lluvia) + la lluvia del WRF9 de Windguru — para compararlo luego con lo real. Silencioso
    y a prueba de fallos. La parte WRF9 NO depende de forecast_df (se archiva aunque no haya
    previsión Sencrop, p. ej. en el informe diario headless)."""
    try:
        if not supabase_is_configured():
            return
        today = pd.Timestamp.now().normalize()
        issue = today.strftime("%Y-%m-%d")
        # Solo UNA vez por sesión (evita escribir en Supabase en cada render). En headless
        # (informe diario) no hay session_state → salta el except y se archiva igualmente.
        _has_session = True
        try:
            _flag = f"_fc_archived_{issue}"
            if st.session_state.get(_flag):
                return
        except Exception:
            _has_session = False
        _by_date = {}   # target_date(str) -> {campos}
        # --- Sencrop (moteado/monilia/oídio/lluvia): solo si hay forecast ---
        # days_back=14 (NO 0): el detector de mojadura necesita histórico de contexto para
        # que el valor archivado COINCIDA con el de la gráfica de Decisiones.
        if forecast_df is not None and not forecast_df.empty:
            risk = build_risk_timeline(history_df, forecast_df, days_back=14)
            if not risk.empty and "Es_prediccion" in risk.columns:
                for _, r in risk[risk["Es_prediccion"] == True].iterrows():
                    d = pd.Timestamp(r["Fecha"]).normalize()
                    # NO archivar el día en curso (horizonte 0). build_risk_timeline marca
                    # HOY como "predicción" porque el día mezcla horas reales (hasta ahora)
                    # con previstas (el resto), pero eso NO es un pronóstico: es el día a
                    # medias, capturado a la hora en que se abrió la app. Al evaluar se toma
                    # siempre el horizonte más corto, así que ese registro se colaba como si
                    # fuera "la última previsión" y falseaba todo:
                    #   · lluvia — a las 8:00 llevaba 0 mm y la lluvia caía por la tarde
                    #     → Sencrop salía con 0,0 "la víspera" en 10 de 18 eventos;
                    #   · moteado/monilia — a esa hora el evento de mojadura de la noche aún
                    #     no ha cerrado, así que Mills valía 0 y luego el día acababa en 138.
                    # Se archiva solo desde mañana (horizonte ≥ 1), que sí es previsión.
                    _hz = int((d - today).days)
                    if _hz < 1:
                        continue
                    _e = _by_date.setdefault(d.strftime("%Y-%m-%d"), {})
                    _e["horizon"] = _hz
                    # Se archiva el valor SIN corregir (crudo del modelo). Desde que
                    # build_risk_timeline aplica FORECAST_BIAS_DEFAULTS a los días de
                    # predicción, `Mills_valor` ya viene dividido — si se guardara así,
                    # el cálculo del sesgo se volvería circular y daría 1,0 para siempre.
                    # Se deshace la división para conservar la serie cruda comparable
                    # con lo que se archivó antes de introducir la corrección.
                    _e["pred_mills"] = float(r.get("Mills_valor", np.nan)) * FORECAST_BIAS_DEFAULTS["mills"]
                    _e["pred_monilia"] = float(r.get("Monilia_valor", np.nan)) * FORECAST_BIAS_DEFAULTS["monilia"]
                    _e["pred_oidio"] = float(r.get("Oidio_valor", np.nan)) * FORECAST_BIAS_DEFAULTS["oidio"]
                    _e["pred_rain"] = float(r.get("Lluvia", np.nan))
                    # DE QUÉ FUENTE SALIÓ. Desde el 23/08/2026 la previsión puede venir
                    # de MeteoGalicia en vez de Sencrop, y son modelos distintos: sin
                    # marcarlo, dentro de unos meses la fiabilidad mezclaría dos cosas
                    # como si fueran una y el resultado no significaría nada.
                    try:
                        _e["pred_src"] = str(st.session_state.get("_forecast_src", "sencrop"))
                    except Exception:
                        _e["pred_src"] = "sencrop"
        # --- Lluvia WRF9 (Windguru): independiente de forecast_df ---
        try:
            for d, mm in (windguru_wrf9_daily_rain() or {}).items():
                d = pd.Timestamp(d).normalize()
                if d <= today:
                    continue          # horizonte 0 fuera: ver comentario de Sencrop arriba
                _e = _by_date.setdefault(d.strftime("%Y-%m-%d"), {})
                _e["horizon"] = int((d - today).days)
                _e["pred_rain_wrf"] = float(mm)
        except Exception:
            pass
        # --- Lluvia WRF MeteoGalicia (1 km oficial): independiente de forecast_df ---
        try:
            for d, mm in (meteosix_wrf_daily_rain() or {}).items():
                d = pd.Timestamp(d).normalize()
                if d <= today:
                    continue          # horizonte 0 fuera: ver comentario de Sencrop arriba
                _e = _by_date.setdefault(d.strftime("%Y-%m-%d"), {})
                _e["horizon"] = int((d - today).days)
                _e["pred_rain_mg"] = float(mm)
        except Exception:
            pass
        if not _by_date:
            return
        new = pd.DataFrame([{"issue_date": issue, "target_date": td, **v}
                            for td, v in _by_date.items()])
        arch = load_forecast_archive()
        _K = ["issue_date", "target_date"]
        if arch is not None and not arch.empty:
            # combine_first: la fila NUEVA manda donde tiene dato; la vieja rellena huecos →
            # una escritura solo-WRF no borra las pred. Sencrop del mismo día, y viceversa.
            out = new.set_index(_K).combine_first(arch.set_index(_K)).reset_index()
        else:
            out = new
        if upload_forecast_archive(out):
            if _has_session:
                try:
                    st.session_state[_flag] = True
                except Exception:
                    pass
            try:
                _download_forecast_archive.clear()
            except Exception:
                pass
    except Exception:
        pass


def _mg_merge_sensor(history_df, archive_df=None, max_h=84):
    """Cruce previsión horaria de MeteoGalicia ↔ sensor, por instante. Base común de la
    comparación global y del desglose. De cada hora se toma la emisión más reciente."""
    if archive_df is None:
        archive_df = load_mg_hourly_archive()
    if archive_df is None or archive_df.empty or history_df is None or history_df.empty:
        return pd.DataFrame()
    a = archive_df.copy()
    a["target_dt"] = pd.to_datetime(a.get("target_dt"), errors="coerce")
    a["horizon_h"] = pd.to_numeric(a.get("horizon_h"), errors="coerce")
    a = a.dropna(subset=["target_dt"])
    a = a[(a["horizon_h"] >= 1) & (a["horizon_h"] <= max_h)]
    if a.empty:
        return pd.DataFrame()
    a = a.sort_values("horizon_h").drop_duplicates("target_dt", keep="first")
    h = history_df.copy()
    h["fecha_hora"] = pd.to_datetime(h["fecha_hora"], errors="coerce")
    h = h.dropna(subset=["fecha_hora"])
    return a.merge(h[["fecha_hora", "temp_media", "hr_media", "lluvia_mm"]],
                   left_on="target_dt", right_on="fecha_hora", how="inner")


def mg_hourly_detalle(history_df, archive_df=None, max_h=84, rh_thr=92.0):
    """DÓNDE se equivoca MeteoGalicia, no solo cuánto.

    Un error de 5 puntos de humedad no vale lo mismo a las 6:00 con el sensor al 90 %
    que a las 15:00 con el 60 %: el primero decide si esa hora cuenta como **hoja
    mojada** y el segundo no le importa a nadie. El error medio global mezcla los dos y
    esconde justo lo que hay que saber.

    Devuelve (por_humedad, por_franja_horaria, metricas_umbral).
    """
    m = _mg_merge_sensor(history_df, archive_df, max_h)
    if m.empty:
        return pd.DataFrame(), pd.DataFrame(), {}
    m = m.copy()
    m["_hr_r"] = pd.to_numeric(m["hr_media"], errors="coerce")
    m["_hr_p"] = pd.to_numeric(m["mg_hr"], errors="coerce")
    m["_t_r"] = pd.to_numeric(m["temp_media"], errors="coerce")
    m["_t_p"] = pd.to_numeric(m["mg_temp"], errors="coerce")

    def _bloque(g):
        _dh = (g["_hr_p"] - g["_hr_r"]).dropna()
        _dt = (g["_t_p"] - g["_t_r"]).dropna()
        return {
            "Horas": len(g),
            "HR sesgo": f"{_dh.mean():+.1f}" if len(_dh) else "—",
            "HR error": f"{_dh.abs().mean():.1f}" if len(_dh) else "—",
            "Temp sesgo": f"{_dt.mean():+.1f}" if len(_dt) else "—",
            "Temp error": f"{_dt.abs().mean():.1f}" if len(_dt) else "—",
        }

    # ── Por FRANJA DE HUMEDAD REAL. Los cortes no son redondos por gusto: se ponen
    #    alrededor del umbral de mojadura, que es donde el error cambia decisiones.
    _lo, _hi = rh_thr - 7, rh_thr
    _et = [f"Seca (<{_lo:.0f} %)", f"Al filo ({_lo:.0f}-{_hi:.0f} %)", f"Húmeda (≥{_hi:.0f} %)"]
    m["_fr_hr"] = pd.cut(m["_hr_r"], [-1, _lo, _hi, 1000], labels=_et)
    _f1 = [{"Humedad real": str(k), **_bloque(g)}
           for k, g in m.groupby("_fr_hr", observed=True) if len(g)]

    # ── Por FRANJA HORARIA. La mojadura se forma de noche y de madrugada: ahí es donde
    #    el acierto importa, y donde un modelo de malla lo tiene más difícil.
    _hh = m["target_dt"].dt.hour
    m["_fr_h"] = pd.cut(_hh, [-1, 5, 11, 17, 23],
                        labels=["Madrugada (0-5)", "Mañana (6-11)",
                                "Tarde (12-17)", "Noche (18-23)"])
    _f2 = [{"Franja": str(k), **_bloque(g)}
           for k, g in m.groupby("_fr_h", observed=True) if len(g)]

    # ── LO QUE DE VERDAD DECIDE: ¿acierta al cruzar el umbral de mojadura? Da igual
    #    errar por 4 puntos si los dos quedan del mismo lado del umbral; errar por 1
    #    justo en el corte sí cambia la decisión.
    _v = m.dropna(subset=["_hr_r", "_hr_p"])
    _met = {}
    if len(_v):
        _real = _v["_hr_r"] >= rh_thr
        _prev = _v["_hr_p"] >= rh_thr
        _met = {
            "umbral": rh_thr,
            "n": len(_v),
            "reales": int(_real.sum()),
            "aciertos": int((_real & _prev).sum()),
            "escapes": int((_real & ~_prev).sum()),
            "falsas": int((~_real & _prev).sum()),
        }
    # ── LA LLUVIA, HORA A HORA. Pesa más que la humedad: en el estimador de mojadura la
    #    PRIMERA condición es «lluvia > 0,1 mm», así que una hora con lluvia prevista
    #    cuenta como hoja mojada sin mirar cuánta. Si el modelo anuncia 4,5 mm y caen
    #    0,5, se inventa horas de mojadura y el riesgo se dispara — pasó los días 28 a
    #    30/08/2026, con la previsión saturada en 150 y un real de 8 a 47.
    #    El error medio en mm no sirve para verlo: en días secos sale minúsculo y parece
    #    que acierta. Lo que importa es cuántas HORAS de lluvia ve y cuántas inventa.
    _lv = m.dropna(subset=["lluvia_mm", "mg_rain"])
    if len(_lv):
        _LL = 0.1                       # el mismo corte que usa el estimador
        _lr = pd.to_numeric(_lv["lluvia_mm"], errors="coerce") > _LL
        _lp = pd.to_numeric(_lv["mg_rain"], errors="coerce") > _LL
        _met["lluvia"] = {
            "n": len(_lv),
            "reales": int(_lr.sum()),
            "aciertos": int((_lr & _lp).sum()),
            "escapes": int((_lr & ~_lp).sum()),
            "falsas": int((~_lr & _lp).sum()),
            "mm_real": float(pd.to_numeric(_lv["lluvia_mm"], errors="coerce").sum()),
            "mm_prev": float(pd.to_numeric(_lv["mg_rain"], errors="coerce").sum()),
        }
    return pd.DataFrame(_f1), pd.DataFrame(_f2), _met


def mg_umbral_sweep(history_df, archive_df=None, max_h=84, rh_thr=92.0):
    """¿Qué umbral de humedad habría que aplicarle a MeteoGalicia?

    MeteoGalicia se queda **corta** de humedad frente al sensor, así que aplicarle el
    mismo umbral (92 %) le hace perder horas de mojadura que sí ocurrieron: con una
    semana de datos, 30 de 68. Bajarle el umbral SOLO A ELLA compensa ese sesgo sin
    tocar el sensor ni el modelo de infección.

    No se elige a ojo: se barren los candidatos y se ve qué se gana y qué se paga. Cada
    punto que se baja recupera escapes (mojadura real no vista → infecciones sin avisar)
    pero añade falsas (mojadura inventada → tratamientos de más). El punto bueno es
    donde los escapes caen mucho y las falsas todavía no se disparan.

    La referencia SIEMPRE es el sensor con su umbral real; lo único que se mueve es el
    listón que se le pide a la previsión.
    """
    m = _mg_merge_sensor(history_df, archive_df, max_h)
    if m.empty:
        return pd.DataFrame()
    _r = pd.to_numeric(m["hr_media"], errors="coerce")
    _p = pd.to_numeric(m["mg_hr"], errors="coerce")
    _ok = _r.notna() & _p.notna()
    _r, _p = _r[_ok], _p[_ok]
    if _r.empty:
        return pd.DataFrame()
    _real = _r >= rh_thr
    _n_real = int(_real.sum())
    filas = []
    for _u in [rh_thr - k for k in (0, 2, 4, 5, 6, 8, 10)]:
        _prev = _p >= _u
        _ac = int((_real & _prev).sum())
        _es = int((_real & ~_prev).sum())
        _fa = int((~_real & _prev).sum())
        filas.append({
            "Umbral para MG": f"{_u:.0f} %" + ("  (el del sensor)" if _u == rh_thr else ""),
            "Horas mojadura vistas": f"{_ac} de {_n_real}" if _n_real else "—",
            "% recuperado": (round(100 * _ac / _n_real) if _n_real else 0),
            "Escapes (no la vio)": _es,
            "Falsas (se la inventó)": _fa,
        })
    return pd.DataFrame(filas)


def mg_hourly_vs_sensor(history_df, archive_df=None, max_h=84):
    """Compara la previsión HORARIA de MeteoGalicia con lo que midió el sensor.

    Esta comparación es distinta de la del panel de fiabilidad, y a propósito: allí se
    miden ÍNDICES de riesgo, que salen de pasar temperatura y HR por nuestro estimador
    de hoja mojada. Cuando un aviso falla no se sabe de quién es la culpa. Aquí se
    comparan las variables **crudas** contra el sensor, sin el estimador de por medio.

    De cada hora se toma la emisión más reciente (horizonte más corto). Devuelve
    (DataFrame por tramo de antelación, meta) o (None, meta)."""
    try:
        if archive_df is None:
            archive_df = load_mg_hourly_archive()
        if archive_df is None or archive_df.empty or history_df is None or history_df.empty:
            return None, {"n": 0}
        a = archive_df.copy()
        a["target_dt"] = pd.to_datetime(a.get("target_dt"), errors="coerce")
        a["horizon_h"] = pd.to_numeric(a.get("horizon_h"), errors="coerce")
        a = a.dropna(subset=["target_dt"])
        a = a[(a["horizon_h"] >= 1) & (a["horizon_h"] <= max_h)]
        if a.empty:
            return None, {"n": 0}
        a = a.sort_values("horizon_h").drop_duplicates("target_dt", keep="first")
        h = history_df.copy()
        h["fecha_hora"] = pd.to_datetime(h["fecha_hora"], errors="coerce")
        h = h.dropna(subset=["fecha_hora"])
        m = a.merge(h[["fecha_hora", "temp_media", "hr_media", "lluvia_mm"]],
                    left_on="target_dt", right_on="fecha_hora", how="inner")
        if m.empty:
            return None, {"n": 0, "pendiente": len(a)}
        # Tramos de antelación: importa más acertar a 1 día que a 3.
        m["tramo"] = pd.cut(m["horizon_h"], [0, 24, 48, 84],
                            labels=["≤1 día", "1-2 días", "2-3,5 días"])
        filas = []
        for _t, g in m.groupby("tramo", observed=True):
            _f = {"Antelación": str(_t), "Horas": len(g)}
            for _p, _r, _n in (("mg_temp", "temp_media", "Temp"),
                               ("mg_hr", "hr_media", "HR"),
                               ("mg_rain", "lluvia_mm", "Lluvia")):
                _d = pd.to_numeric(g[_p], errors="coerce") - pd.to_numeric(g[_r], errors="coerce")
                _d = _d.dropna()
                if _d.empty:
                    _f[f"{_n} sesgo"], _f[f"{_n} error"] = "—", "—"
                else:
                    # Sesgo = se pasa o se queda corto (con signo). Error = cuánto se
                    # equivoca de media, sin signo. Los dos hacen falta: un sesgo de 0
                    # puede esconder errores grandes que se compensan.
                    _f[f"{_n} sesgo"] = f"{_d.mean():+.1f}"
                    _f[f"{_n} error"] = f"{_d.abs().mean():.1f}"
            filas.append(_f)
        return pd.DataFrame(filas), {"n": len(m), "desde": m["target_dt"].min(),
                                     "hasta": m["target_dt"].max()}
    except Exception:
        return None, {"n": 0}


def forecast_reliability(history_df, archive_df=None):
    """Compara el riesgo PREVISTO (archivo) con el REAL (histórico, sensor) para los
    días ya transcurridos. Devuelve (DataFrame resumen, meta) o (None, meta)."""
    try:
        if archive_df is None:
            archive_df = load_forecast_archive()
        if archive_df is None or archive_df.empty or history_df is None or history_df.empty:
            return None, {"n": 0}
        today = pd.Timestamp.now().normalize()
        oldest = pd.to_datetime(archive_df.get("target_date"), errors="coerce").min()
        days_back = 60 if pd.isna(oldest) else min(max(int((today - oldest).days) + 5, 15), 730)
        actual = build_risk_timeline(history_df, pd.DataFrame(), days_back=days_back)
        if actual.empty:
            return None, {"n": 0}
        actual = actual.copy()
        actual["target_date"] = pd.to_datetime(actual["Fecha"]).dt.strftime("%Y-%m-%d")
        a = actual.drop_duplicates("target_date").set_index("target_date")
        THR, RAIN = 100.0, 0.2  # lluvia REAL: precipitación medible (≥0,2 mm/día)
        # Umbral para considerar que un modelo ANUNCIÓ lluvia: cualquier cantidad > 0.
        # Va aparte del umbral de lluvia real porque aquí se juzga el HECHO, no la
        # cantidad. Con un solo umbral, una previsión de 0,1 mm contaba como «dijo que
        # estaría seco» y se apuntaba como escape (MeteoGalicia el 15/08: previó 0,1 y
        # cayeron 1,0). Mismo criterio que el coloreado de la tabla día a día.
        RAIN_PRED = 0.05
        # Banda "casi" (jul-2026): en un día de evento real, una previsión que llega al
        # ≥90% del umbral (≥90 cuando el real ≥100) cuenta como AVISADA — el modelo sí
        # marcó riesgo alto; el corte exacto en 100 es demasiado brusco con muestras
        # pequeñas (p. ej. previsión 97 vs real 100). Solo afecta a ESTA métrica de
        # fiabilidad, NO al umbral 100 que dispara tratamientos. La lluvia no lleva banda.
        NEAR = 0.90
        recs = []
        for _, r in archive_df.iterrows():
            td = str(r.get("target_date"))
            if td not in a.index:
                continue
            # Horizonte 0 fuera: día en curso a media mañana, no previsión (ver
            # archive_today_forecast). Falseaba la métrica hacia el lado malo.
            _hz_r = pd.to_numeric(r.get("horizon"), errors="coerce")
            if pd.isna(_hz_r) or int(_hz_r) < 1:
                continue
            # La previsión archivada es CRUDA; el real está corregido y topado. Compararlos
            # tal cual medía el modelo más generoso de lo que es: un previsto crudo de 120
            # contaba como aviso (≥100) cuando corregido son 73. Se pasan a la misma
            # escala, con el factor de la fuente con que se archivó cada uno.
            _src_r = r.get("pred_src") or "sencrop"
            _mp = float(pred_en_escala_real(r.get("pred_mills", 0), "mills", _src_r) or 0)
            _mr = float(a.loc[td, "Mills_valor"])
            _op = float(pred_en_escala_real(r.get("pred_monilia", 0), "monilia", _src_r) or 0)
            _omr = float(a.loc[td, "Monilia_valor"])
            _dp = float(pred_en_escala_real(r.get("pred_oidio", 0), "oidio", _src_r) or 0)
            _dr = float(a.loc[td, "Oidio_valor"])
            _lp = float(r.get("pred_rain", 0));    _lr = float(a.loc[td, "Lluvia"])
            _lwp = r.get("pred_rain_wrf", np.nan)
            _lwp = float(_lwp) if pd.notna(_lwp) else np.nan
            _lmg = r.get("pred_rain_mg", np.nan)
            _lmg = float(_lmg) if pd.notna(_lmg) else np.nan
            recs.append({
                "target_date": td,
                "horizon": int(r.get("horizon", 0)),
                # Booleanas (corte estricto ≥umbral) — usadas por la tabla de antelación.
                "moteado_p": _mp >= THR,  "moteado_r": _mr >= THR,
                "monilia_p": _op >= THR,  "monilia_r": _omr >= THR,
                "oidio_p":   _dp >= THR,  "oidio_r":   _dr >= THR,
                "lluvia_p":  _lp >= RAIN_PRED, "lluvia_r":  _lr >= RAIN,
                # Numéricas — el resumen aplica sobre ellas la banda "casi".
                "moteado_pv": _mp, "moteado_rv": _mr,
                "monilia_pv": _op, "monilia_rv": _omr,
                "oidio_pv":   _dp, "oidio_rv":   _dr,
                "lluvia_pv":  _lp, "lluvia_rv":  _lr,
                "lluvia_wrf_pv": _lwp,   # lluvia prevista por el WRF9 (Windguru); NaN si no archivada
                "lluvia_mg_pv":  _lmg,   # lluvia prevista por el WRF 1 km (MeteoGalicia); NaN si no archivada
            })
        comp = pd.DataFrame(recs)
        if comp.empty:
            return None, {"n": 0}
        _n_dias = int(comp["target_date"].nunique())  # días NATURALES distintos verificados
        # Tabla principal POR DÍA: una fila por día real, usando la previsión MÁS
        # RECIENTE de cada día (la más fiable). Así "acertó X de N días" se cuenta por
        # días, no por comparaciones. (La tabla de antelación de abajo sí usa todas.)
        comp_day = comp.sort_values("horizon").drop_duplicates("target_date", keep="first").copy()
        comp_day["_dt"] = pd.to_datetime(comp_day["target_date"], errors="coerce").dt.normalize()
        out_rows = []
        # `tol` = tolerancia temporal en días (±1 para infecciones: un aviso/evento a un día
        # de distancia = mismo episodio, el modelo no clava la hora de corte. La lluvia va
        # estricta, tol=0, porque es una medida diaria directa, no un episodio).
        # `thr` = umbral del valor REAL (¿hubo evento?). `thr_p` = umbral de la PREVISIÓN
        # (¿el modelo lo anunció?). En infecciones coinciden (100); en lluvia NO: real
        # ≥0,2 mm, pero anunciar lluvia es cualquier cantidad > 0.
        for label, pv, rv, thr, thr_p, near, tol in [
                ("🍄 Moteado", "moteado_pv", "moteado_rv", THR,  THR,       NEAR, 1),
                ("🟤 Monilia", "monilia_pv", "monilia_rv", THR,  THR,       NEAR, 1),
                ("⚪ Oídio",   "oidio_pv",   "oidio_rv",   THR,  THR,       NEAR, 1),
                ("🌧️ Lluvia", "lluvia_pv",  "lluvia_rv",  RAIN, RAIN_PRED, 1.0, 0),
                ("🌧️ Lluvia WRF9", "lluvia_wrf_pv", "lluvia_rv", RAIN, RAIN_PRED, 1.0, 0),
                ("🌧️ Lluvia MeteoGal.", "lluvia_mg_pv", "lluvia_rv", RAIN, RAIN_PRED, 1.0, 0)]:
            # Estado por día: (aviso_pleno ≥umbral, aviso_casi ≥90%, evento_real).
            _day = {}
            for _, _rw in comp_day.iterrows():
                _d = _rw["_dt"]
                if pd.isna(_d):
                    continue
                _pvv = _rw[pv]
                if pd.isna(_pvv):   # ese día ESE modelo no predijo (p.ej. WRF9 antes de existir) → no cuenta
                    continue
                # (aviso pleno, aviso "casi", evento real). Los dos primeros se miden
                # contra thr_p (umbral de la PREVISIÓN); el tercero contra thr (el REAL).
                _day[_d] = (float(_pvv) >= thr_p, float(_pvv) >= thr_p * near,
                            float(_rw[rv]) >= thr)
            _nd = len(_day)         # días que ESTE modelo predijo (su propio denominador)

            def _near(_d, _i, _day=_day, _tol=tol):
                """¿Algún día en ±tol cumple la condición _i (0=aviso pleno,1=casi,2=evento)?"""
                return any(_day.get(_d + pd.Timedelta(days=k), (False, False, False))[_i]
                           for k in range(-_tol, _tol + 1))

            reales = tp = fn = fp = aciertos = 0
            for _d, (_pf, _pw, _re) in _day.items():
                if _re:                                    # día de EVENTO real
                    reales += 1
                    if _near(_d, 1):                       # avisó (≥90%) en ±tol → pillado
                        tp += 1; aciertos += 1
                    else:
                        fn += 1                            # se escapó (ni a ±tol)
                else:                                      # sin evento
                    if _pf and not _near(_d, 2):           # aviso pleno y NINGÚN evento en ±tol
                        fp += 1                            # falsa alarma real
                    else:
                        aciertos += 1                      # sin aviso, o "cola" de evento (excusada)
            # Fiabilidad basada en LO QUE IMPORTA: ¿pilla los eventos de infección reales?
            # Un "acierto" global alto no vale si se le escapan eventos (premia días tranquilos).
            if reales == 0:
                _fiab = "🟡 Sin eventos aún"
            elif fn > 0:
                _fiab = "🔴 Escapan eventos"
            elif _nd < 7 or reales < 2:
                _fiab = "🟡 Promete (pocos datos)"
            else:
                _fiab = "🟢 Buena"
            # EVENTOS QUE NI SIQUIERA SE EVALUARON. Arriba se descartan los días que no
            # están en el archivo (`if td not in a.index: continue`): sin previsión no hay
            # nada que comparar. Pero si ESE día hubo infección, desaparecía de la cuenta
            # y el resumen podía decir «avisó de TODAS» habiendo eventos sin cubrir.
            # Pasó el 25/08/2026, en el hueco entre que Sencrop dejó de servir previsión y
            # que se montó la de MeteoGalicia: la tabla día a día lo pintaba en rojo y el
            # resumen seguía diciendo 100 %. No es culpa del modelo — no había modelo —
            # pero el usuario tiene que saberlo: esos días estuvo sin avisador.
            _sin_cub = 0
            _col_real = {"🍄 Moteado": "Mills_valor", "🟤 Monilia": "Monilia_valor",
                         "⚪ Oídio": "Oidio_valor"}.get(label)
            if _col_real and _col_real in a.columns:
                try:
                    _ev_all = a.index[pd.to_numeric(a[_col_real], errors="coerce") >= thr]
                    _sin_cub = int(sum(1 for _d in _ev_all if _d not in set(comp_day["target_date"])))
                except Exception:
                    _sin_cub = 0
            out_rows.append({
                "Qué": label,
                "Fiabilidad": ("🟠 Días sin previsión" if (_sin_cub and _fiab == "🟢 Buena")
                               else _fiab),
                "Eventos avisados (lo que importa)": (
                    f"{tp} de {reales} ({round(tp / reales * 100)}%)" if reales else "sin eventos aún"),
                "Acertó (de los días)": f"{aciertos} de {_nd}",
                "Falsas alarmas (avisó, no pasó)": fp,
                "Se le escapó (no avisó, sí pasó)": (f"{fn} de {reales}" if reales else "0"),
                "Sin previsión (no se pudo avisar)": _sin_cub,
            })
        meta = {"n": len(comp), "n_dias": _n_dias, "comp": comp,
                "sin_cubrir": int(sum(r.get("Sin previsión (no se pudo avisar)", 0)
                                      for r in out_rows)),
                "since": str(archive_df.get("issue_date", pd.Series(dtype=str)).min())}
        return pd.DataFrame(out_rows), meta
    except Exception:
        return None, {"n": 0}


def forecast_bias_correction(history_df, archive_df=None, min_real=20.0):
    """¿Y si en vez de subir el umbral, corregimos el número previsto?

    Es corrección de sesgo (*bias correction*), técnica estándar en pronóstico:
    si la previsión infla de forma sistemática, se divide por ese factor y el
    umbral vuelve a ser el mismo en los dos lados (100). Más limpio que mover el
    punto de corte, porque además deja la gráfica comparable con lo real.

    El factor se estima con la MEDIANA del ratio previsto/real (no la media: hay
    outliers de ×3,5 que la arrastrarían) y solo sobre días con real ≥ `min_real`,
    porque dividir por valores casi cero da ratios absurdos.

    Devuelve (factores, comparativa):
      · factores   — factor y dispersión por enfermedad. Si el rango
                     intercuartílico es ancho, la corrección vale poco: el sesgo
                     no es constante y un factor único no lo captura.
      · comparativa— escapes y falsas alarmas de cada estrategia, para elegir con
                     datos: subir el umbral vs corregir el número.
    """
    vacio = (pd.DataFrame(), pd.DataFrame())
    try:
        if archive_df is None:
            archive_df = load_forecast_archive()
        if archive_df is None or archive_df.empty or history_df is None or history_df.empty:
            return vacio
        today = pd.Timestamp.now().normalize()
        oldest = pd.to_datetime(archive_df.get("target_date"), errors="coerce").min()
        days_back = 60 if pd.isna(oldest) else min(max(int((today - oldest).days) + 5, 15), 730)
        actual = build_risk_timeline(history_df, pd.DataFrame(), days_back=days_back)
        if actual is None or actual.empty:
            return vacio
        actual = actual.copy()
        actual["_d"] = pd.to_datetime(actual["Fecha"]).dt.normalize()
        a = actual.drop_duplicates("_d").set_index("_d")

        ad = archive_df.copy()
        ad["_d"] = pd.to_datetime(ad.get("target_date"), errors="coerce").dt.normalize()
        ad["_h"] = pd.to_numeric(ad.get("horizon"), errors="coerce")
        ad = ad.dropna(subset=["_d", "_h"])
        ad = ad[ad["_h"] >= 1]

        fac_rows, cmp_rows = [], []
        for etiqueta, pcol, rcol in [("🍄 Moteado", "pred_mills", "Mills_valor"),
                                     ("🟤 Monilia", "pred_monilia", "Monilia_valor")]:
            if pcol not in ad.columns or rcol not in a.columns:
                continue
            g = ad[["_d", pcol]].copy()
            g[pcol] = pd.to_numeric(g[pcol], errors="coerce")
            g = g.dropna(subset=[pcol]).groupby("_d")[pcol].max()
            pares = []
            for d in g.index:
                if d not in a.index:
                    continue
                r = pd.to_numeric(a.loc[d, rcol], errors="coerce")
                if pd.isna(r):
                    continue
                pares.append((float(g[d]), float(r)))
            if not pares:
                continue
            _rat = [p / r for p, r in pares if r >= min_real and r > 0]
            if not _rat:
                continue
            _rat = np.array(_rat)
            factor = float(np.median(_rat))
            q1, q3 = float(np.percentile(_rat, 25)), float(np.percentile(_rat, 75))
            _d_ini = min(g.index) if len(g.index) else None
            _d_fin = max(g.index) if len(g.index) else None
            fac_rows.append({
                "Qué": etiqueta, "Factor (mediana)": round(factor, 2),
                "Rango 50 % central": f"{q1:.2f} – {q3:.2f}",
                "Mín – Máx": f"{_rat.min():.2f} – {_rat.max():.2f}",
                # Se separan los dos números porque "Días usados" solo se prestaba a
                # pensar que se miran los últimos N días. No: se usa TODO el archivo, y
                # de ahí se filtran los días con real ≥ min_real (dividir por valores
                # casi cero da ratios absurdos: 5 previsto sobre 1 real serían ×5).
                "Días comparables": len(pares),
                f"…con real ≥{int(min_real)} (los que cuentan)": len(_rat),
                "Periodo": (f"{_d_ini:%d/%m} – {_d_fin:%d/%m}"
                            if _d_ini is not None else "—"),
                "¿Sirve un factor único?": ("sí, sesgo estable" if (q3 - q1) <= 0.6
                                            else "dudoso, muy disperso"),
            })
            # Comparar estrategias sobre TODOS los días (no solo los de real alto)
            _thr_actual = forecast_warn_threshold("mills" if "Moteado" in etiqueta else "monilia")
            for nombre, corr, thr in [
                    ("Sin corregir · umbral 100", 1.0, 100.0),
                    (f"Sin corregir · umbral {int(_thr_actual)} (actual)", 1.0, _thr_actual),
                    ("Corregido · umbral 100", factor, 100.0)]:
                esc = fal = ok = 0
                for p, r in pares:
                    aviso, evento = (p / corr) >= thr, r >= 100.0
                    if evento and aviso:
                        ok += 1
                    elif evento:
                        esc += 1
                    elif aviso:
                        fal += 1
                cmp_rows.append({
                    "Qué": etiqueta, "Estrategia": nombre,
                    "Infecciones avisadas": ok, "🔴 Escapes": esc,
                    "Falsas alarmas": fal,
                    "Total avisos": ok + fal,
                })
        return pd.DataFrame(fac_rows), pd.DataFrame(cmp_rows)
    except Exception:
        return vacio


def forecast_reliability_persistence(history_df, archive_df=None):
    """Fiabilidad medida sobre TODAS las emisiones, no solo la última.

    Mirar únicamente la previsión de horizonte más corto es la forma menos
    informativa de juzgar un pronóstico: tira las emisiones anteriores. Un modelo
    que avisa a 5, 4, 3 y 2 días y se desdice a 1 día **avisó** — y con antelación
    de sobra para tratar. Uno que no dijo nada nunca, no.

    Devuelve (por_evento, resumen, por_horizonte):
      · por_evento    — un día real de evento por fila: cuántas emisiones lo
                        avisaron, con cuánta antelación y qué decía la última.
      · resumen       — por modelo: sostenidos / intermitentes / escapes totales.
      · por_horizonte — acierto por días de antelación: ¿a cuántos días me fío?
    """
    vacio = (pd.DataFrame(), pd.DataFrame(), pd.DataFrame())
    try:
        if archive_df is None:
            archive_df = load_forecast_archive()
        if archive_df is None or archive_df.empty or history_df is None or history_df.empty:
            return vacio
        today = pd.Timestamp.now().normalize()
        oldest = pd.to_datetime(archive_df.get("target_date"), errors="coerce").min()
        days_back = 60 if pd.isna(oldest) else min(max(int((today - oldest).days) + 5, 15), 730)
        actual = build_risk_timeline(history_df, pd.DataFrame(), days_back=days_back)
        if actual is None or actual.empty:
            return vacio
        actual = actual.copy()
        actual["_td"] = pd.to_datetime(actual["Fecha"]).dt.strftime("%Y-%m-%d")
        a = actual.drop_duplicates("_td").set_index("_td")

        ad = archive_df.copy()
        ad["_td"] = pd.to_datetime(ad.get("target_date"), errors="coerce").dt.strftime("%Y-%m-%d")
        ad["_h"] = pd.to_numeric(ad.get("horizon"), errors="coerce")
        ad = ad.dropna(subset=["_td", "_h"])
        # Horizonte 0 fuera: es el día en curso a media mañana, no una previsión.
        ad = ad[ad["_h"] >= 1]

        # (etiqueta, col. archivo, col. real, umbral real, umbral previsión, campo_sesgo)
        MODELOS = [
            ("🍄 Moteado",          "pred_mills",    "Mills_valor",   100.0, 90.0, "mills"),
            ("🟤 Monilia",          "pred_monilia",  "Monilia_valor", 100.0, 90.0, "monilia"),
            ("⚪ Oídio",            "pred_oidio",    "Oidio_valor",   100.0, 90.0, "oidio"),
            ("🌧️ Lluvia WRF9",     "pred_rain_wrf", "Lluvia",          0.2,  0.05, None),
            ("🌧️ Lluvia MeteoGal.", "pred_rain_mg", "Lluvia",          0.2,  0.05, None),
        ]
        # «pred_rain» se etiquetaba como «Lluvia Sencrop», pero es la lluvia de la
        # PREVISIÓN ACTIVA: desde el 25/08/2026 la rellena MeteoGalicia, así que esa fila
        # salía duplicando a «Lluvia MeteoGal.» con otro recuento de emisiones y con un
        # nombre falso. Solo se lista mientras la previsión sea de verdad de Sencrop.
        try:
            _src_activa = st.session_state.get("_forecast_src", "sencrop")
        except Exception:
            _src_activa = "sencrop"
        if _src_activa != "meteogalicia":
            MODELOS.insert(3, ("🌧️ Lluvia Sencrop", "pred_rain", "Lluvia", 0.2, 0.05, None))
        ev_rows, res_rows, hz_rows = [], [], []
        for label, pcol, rcol, thr_r, thr_p, _campo in MODELOS:
            if pcol not in ad.columns or rcol not in a.columns:
                continue
            _cols = ["_td", "_h", pcol] + (["pred_src"] if "pred_src" in ad.columns else [])
            sub = ad[_cols].copy()
            sub[pcol] = pd.to_numeric(sub[pcol], errors="coerce")
            # La previsión se archiva CRUDA (sin corregir el sesgo ni topar). Aquí se
            # compara con el real y se enseña en «Última previsión», así que hay que
            # ponerla en la misma escala: si no, salían 229 al lado de un real de 137.
            if _campo:
                _srcs = (sub["pred_src"] if "pred_src" in sub.columns
                         else pd.Series("sencrop", index=sub.index))
                sub[pcol] = [pred_en_escala_real(_v, _campo, _sc)
                             for _v, _sc in zip(sub[pcol], _srcs.fillna("sencrop"))]
            sub = sub.dropna(subset=[pcol])
            if sub.empty:
                continue
            n_sost = n_int = n_esc = 0
            antelaciones = []
            for td, g in sub.groupby("_td"):
                if td not in a.index:
                    continue                       # día aún sin dato real
                real = pd.to_numeric(a.loc[td, rcol], errors="coerce")
                if pd.isna(real) or float(real) < thr_r:
                    continue                       # solo días de EVENTO real
                g = g.sort_values("_h")
                avisos = g[g[pcol] >= thr_p]
                n_em, n_av = len(g), len(avisos)
                pct = 100.0 * n_av / n_em if n_em else 0.0
                ante = int(avisos["_h"].max()) if n_av else 0
                ultima = float(g.iloc[0][pcol])    # horizonte más corto
                if n_av == 0:
                    estado, n_esc = "🔴 Escape total (no avisó nunca)", n_esc + 1
                elif pct >= 50:
                    estado, n_sost = "🟢 Aviso sostenido", n_sost + 1
                else:
                    estado, n_int = "🟡 Aviso intermitente", n_int + 1
                if n_av:
                    antelaciones.append(ante)
                ev_rows.append({
                    "Día": pd.to_datetime(td).strftime("%d/%m"),
                    "Qué": label, "Estado": estado,
                    "Real": round(float(real), 1),
                    "Avisaron": f"{n_av} de {n_em}",
                    "% emisiones": round(pct),
                    "Antelación máx (días)": ante,
                    "Última previsión": round(ultima, 1),
                })
            n_ev = n_sost + n_int + n_esc
            if n_ev:
                res_rows.append({
                    "Qué": label,
                    "Eventos reales": n_ev,
                    "🟢 Aviso sostenido": n_sost,
                    "🟡 Intermitente": n_int,
                    "🔴 Escape total": n_esc,
                    "Avisados (algo)": f"{n_sost + n_int} de {n_ev} "
                                       f"({round(100*(n_sost+n_int)/n_ev)}%)",
                    "Antelación media (días)": (round(float(np.mean(antelaciones)), 1)
                                                if antelaciones else 0.0),
                })
            # ── Acierto por horizonte: ¿a cuántos días vista me puedo fiar? ──
            for h in range(1, 8):
                gh = sub[sub["_h"] == h]
                if gh.empty:
                    continue
                ok = tot = 0
                for _, rw in gh.iterrows():
                    if rw["_td"] not in a.index:
                        continue
                    real = pd.to_numeric(a.loc[rw["_td"], rcol], errors="coerce")
                    if pd.isna(real) or float(real) < thr_r:
                        continue
                    tot += 1
                    if float(rw[pcol]) >= thr_p:
                        ok += 1
                if tot:
                    hz_rows.append({"Qué": label, "Antelación (días)": h,
                                    "Eventos": tot, "Avisados": ok,
                                    "% acierto": round(100.0 * ok / tot)})
        por_evento = (pd.DataFrame(ev_rows).sort_values(["Día", "Qué"], ascending=[False, True])
                      if ev_rows else pd.DataFrame())
        resumen = pd.DataFrame(res_rows) if res_rows else pd.DataFrame()
        por_hz = (pd.DataFrame(hz_rows).pivot(index="Antelación (días)", columns="Qué",
                                              values="% acierto").reset_index()
                  if hz_rows else pd.DataFrame())
        return por_evento, resumen, por_hz
    except Exception:
        return vacio


# Factor de sesgo POR FUENTE. El 1,65/1,67 se midió sobre Sencrop; MeteoGalicia es otro
# modelo y su sesgo aún no está medido, así que va 1,0 hasta que haya datos. Cada
# previsión se archiva con su `pred_src`, así que se puede aplicar el que le toca.
FORECAST_BIAS_BY_SRC = {
    "sencrop": FORECAST_BIAS_DEFAULTS,
    "meteogalicia": {"mills": 1.0, "monilia": 1.0, "oidio": 1.0},
}


def pred_en_escala_real(valor, campo, src="sencrop", tope=150.0):
    """Previsión ARCHIVADA (cruda) llevada a la misma escala que el valor real.

    El archivo guarda la previsión **sin** corregir el sesgo, y a propósito: si guardara
    el valor ya dividido, el cálculo del factor se mordería la cola y daría 1,0 para
    siempre. Pero para **enseñarla junto al real** —y para medir fiabilidad contra él—
    hay que aplicarle la misma corrección y el mismo tope, o se comparan escalas
    distintas. Se veía en la tabla: un previsto de **229** al lado de un real topado en
    **150**, que no es que fuera mayor, es que estaba sin corregir (229/1,65 = 139).

    Y no es solo cosmético: en fiabilidad, un previsto crudo de 120 contaba como aviso
    (≥100) cuando corregido son 73 y no habría avisado — el modelo salía más generoso
    de lo que es.
    """
    try:
        v = float(valor)
    except Exception:
        return np.nan
    if pd.isna(v):
        return np.nan
    _f = FORECAST_BIAS_BY_SRC.get(str(src or "sencrop"),
                                  FORECAST_BIAS_BY_SRC["sencrop"]).get(campo, 1.0)
    try:
        _f = float(_f) or 1.0
    except Exception:
        _f = 1.0
    return min(v / _f, float(tope))


def forecast_reliability_daily(history_df, archive_df=None, forecast_df=None, days=30, days_fwd=7, wrf_rain=None, mg_rain=None):
    """Tabla día a día PREVISTO vs REAL. Incluye:
      · Días FUTUROS (🔮): la previsión EN VIVO de la gráfica (real aún pendiente).
      · Días PASADOS: lo que se PREDIJO entonces (archivo) vs lo REAL (sensor).
    Así se ven las predicciones escritas hoy y, según llega cada día, se rellena el
    valor real. Orden descendente (futuro arriba, luego lo más reciente)."""
    try:
        if archive_df is None:
            archive_df = load_forecast_archive()
        if history_df is None or history_df.empty:
            return pd.DataFrame()
        today = pd.Timestamp.now().normalize()
        _fc = forecast_df if forecast_df is not None else pd.DataFrame()
        risk = build_risk_timeline(history_df, _fc, days_back=int(days))
        if risk is None or risk.empty:
            return pd.DataFrame()
        risk = risk.copy()
        risk["_d"] = pd.to_datetime(risk["Fecha"]).dt.normalize()
        risk = risk.drop_duplicates("_d")
        risk = risk[risk["_d"] <= today + pd.Timedelta(days=int(days_fwd))]

        # Previsión archivada de cada día: la MÁS RECIENTE (menor horizonte = la del
        # propio día). Ahora es correcta porque el archivado usa el mismo cálculo que
        # la gráfica (build_risk_timeline con contexto), no days_back=0.
        pred_map = {}
        if archive_df is not None and not archive_df.empty and "target_date" in archive_df.columns:
            ad = archive_df.copy()
            ad["_h"] = pd.to_numeric(ad.get("horizon"), errors="coerce").fillna(99)
            # Descartar horizonte 0: es el día en curso capturado a media mañana, no una
            # previsión (ver archive_today_forecast). Se archivó así hasta ago-2026 y como
            # aquí se toma el horizonte MÁS CORTO, se colaba como "la última previsión".
            ad = ad[ad["_h"] >= 1]
            ad = ad.sort_values("_h").drop_duplicates("target_date", keep="first")
            for _, r in ad.iterrows():
                pred_map[str(r.get("target_date"))] = r

        def _si(x):   # entero como texto; "—" si falta
            return str(int(round(float(x)))) if pd.notna(x) else "—"

        def _sr(x):   # 1 decimal como texto; "—" si falta
            return f"{float(x):.1f}" if pd.notna(x) else "—"

        # Evento de hoja mojada EN CURSO ahora: el valor real de HOY se muestra
        # provisional (con *) mientras el evento no cierre (sube hasta que la hoja seca).
        _om, _oo, _oab = current_open_wet_event(history_df)

        rows = []
        for _, r in risk.sort_values("_d").iterrows():
            d = r["_d"]
            td = d.strftime("%Y-%m-%d")
            pendiente = bool(r.get("Es_prediccion")) or d >= today
            if pendiente:
                # FUTURO/HOY: previsto = previsión EN VIVO; real aún no ha ocurrido,
                # salvo que HOY haya un evento EN CURSO → valor provisional con "*".
                _hoy_abierto = bool(_oab and d == today)
                # Lluvia MeteoGalicia en días FUTUROS: se intenta el valor en vivo y, si
                # no hay (Streamlit Cloud no consigue conectar con servizos.meteogalicia.gal
                # — nos bloquea las IPs de centro de datos), se cae al valor ARCHIVADO.
                # El informe diario corre en GitHub Actions, que SÍ conecta, y cada mañana
                # archiva la previsión de MeteoGalicia para los próximos días: así la
                # columna se rellena igual sin depender de la conexión de la app.
                _mg_vivo = mg_rain.get(d) if mg_rain else None
                _mg_arch = pred_map.get(td)
                if _mg_vivo is None and _mg_arch is not None:
                    _mg_vivo = _mg_arch.get("pred_rain_mg")
                rows.append({
                    "_sort": d, "Fecha": d.strftime("%d/%m") + (" 🔄" if _hoy_abierto else " 🔮"),
                    "Moteado prev.": _si(r.get("Mills_valor")),
                    "Moteado real": (f"{int(_om)}*" if _hoy_abierto else "—"),
                    "Monilia prev.": _si(r.get("Monilia_valor")),
                    "Monilia real": (f"{int(_oo)}*" if _hoy_abierto else "—"),
                    "Oídio prev.": _si(r.get("Oidio_valor")),     "Oídio real": "—",
                    "Lluvia prev.": _sr(r.get("Lluvia")),
                    "Lluvia WRF9": (_sr(wrf_rain.get(d)) if wrf_rain else "—"),
                    "Lluvia MG": _sr(_mg_vivo),
                    "Lluvia real": "—",
                })
            else:
                pr = pred_map.get(td)
                # El archivo guarda la previsión CRUDA (sin corregir el sesgo ni topar).
                # Aquí va al lado del real, así que hay que ponerla en su misma escala:
                # si no, un previsto de 229 junto a un real de 150 parece mayor cuando en
                # realidad son 139 corregidos. Ver pred_en_escala_real().
                _src_pr = (pr.get("pred_src") if pr is not None else None) or "sencrop"

                def _pp(col, campo):
                    if pr is None:
                        return "—"
                    return _si(pred_en_escala_real(pr.get(col), campo, _src_pr))

                rows.append({
                    "_sort": d, "Fecha": d.strftime("%d/%m"),
                    "Moteado prev.": _pp("pred_mills", "mills"),
                    "Moteado real": _si(r.get("Mills_valor")),
                    "Monilia prev.": _pp("pred_monilia", "monilia"),
                    "Monilia real": _si(r.get("Monilia_valor")),
                    "Oídio prev.": _pp("pred_oidio", "oidio"),
                    "Oídio real": _si(r.get("Oidio_valor")),
                    "Lluvia prev.": (_sr(pr.get("pred_rain")) if pr is not None else "—"),
                    "Lluvia WRF9": (_sr(pr.get("pred_rain_wrf")) if pr is not None else "—"),
                    "Lluvia MG": (_sr(pr.get("pred_rain_mg")) if pr is not None else "—"),
                    "Lluvia real": _sr(r.get("Lluvia")),
                })
        # DÍAS FUTUROS CUANDO NO HAY PREVISIÓN DE SENCROP. El esqueleto temporal de la
        # tabla salía SOLO de build_risk_timeline, que necesita la previsión horaria de
        # Sencrop. Si falta, no había ninguna fila futura — y con ella se perdían de vista
        # WRF9 y MeteoGalicia, que son fuentes INDEPENDIENTES y siguen funcionando
        # (20/08/2026: Sencrop retiró el acceso y la tabla se quedó sin lluvia prevista
        # aunque las otras dos fuentes estaban ahí).
        # La lluvia prevista sí se puede enseñar; el riesgo de infección no, porque
        # necesita temperatura y HR horarias que solo da Sencrop — esas van en "—".
        _cubiertos = {r["_sort"] for r in rows}
        _extra = set()
        for _src in ((wrf_rain or {}), (mg_rain or {})):
            for _d in _src:
                try:
                    _extra.add(pd.Timestamp(_d).normalize())
                except Exception:
                    pass
        for _td_s in pred_map:          # MG/WRF9 archivados por el informe diario
            try:
                _extra.add(pd.Timestamp(_td_s).normalize())
            except Exception:
                pass
        _tope = today + pd.Timedelta(days=int(days_fwd))
        for d in sorted(_extra):
            if d in _cubiertos or d < today or d > _tope:
                continue
            pr = pred_map.get(d.strftime("%Y-%m-%d"))
            _mg_v = (mg_rain or {}).get(d)
            if _mg_v is None and pr is not None:
                _mg_v = pr.get("pred_rain_mg")
            _wrf_v = (wrf_rain or {}).get(d)
            if _wrf_v is None and pr is not None:
                _wrf_v = pr.get("pred_rain_wrf")
            if _mg_v is None and _wrf_v is None:
                continue               # nada que enseñar de ese día
            rows.append({
                "_sort": d, "Fecha": d.strftime("%d/%m") + " 🔮",
                "Moteado prev.": "—", "Moteado real": "—",
                "Monilia prev.": "—", "Monilia real": "—",
                "Oídio prev.": "—",   "Oídio real": "—",
                "Lluvia prev.": "—",
                "Lluvia WRF9": _sr(_wrf_v),
                "Lluvia MG": _sr(_mg_v),
                "Lluvia real": "—",
            })

        if not rows:
            return pd.DataFrame()
        return (pd.DataFrame(rows).sort_values("_sort", ascending=False)
                .drop(columns=["_sort"]).reset_index(drop=True))
    except Exception:
        return pd.DataFrame()


def _dec_treatment_lines_trace(go, treats_df, x_min, x_max, ymax, color="rgba(150,0,200,0.7)",
                               name="Tratamiento"):
    """Una sola traza scatter con TODAS las líneas verticales de tratamiento (dashed)
    pero HOVERABLE: al pasar el ratón por una línea muestra los CAMPOS tratados ese
    día (y el/los productos). Devuelve None si no hay tratamientos en el rango."""
    if treats_df is None or treats_df.empty or "Fecha_dt" not in treats_df.columns:
        return None
    t = treats_df.copy()
    t["Fecha_dt"] = pd.to_datetime(t["Fecha_dt"], errors="coerce")
    t = t.dropna(subset=["Fecha_dt"])
    t = t[(t["Fecha_dt"] >= x_min) & (t["Fecha_dt"] <= x_max)]
    if t.empty:
        return None
    fcol = next((c for c in ["Campos", "Campos reconocidos", "Campo"] if c in t.columns), None)
    pcol = next((c for c in ["Producto", "Productos"] if c in t.columns), None)
    xs, ys, cd = [], [], []
    for d, grp in t.groupby(t["Fecha_dt"].dt.normalize()):
        campos = set()
        if fcol:
            for v in grp[fcol].dropna().astype(str):
                for part in v.replace(";", ",").split(","):
                    p = part.strip()
                    if p and p.lower() not in ("nan", "none", ""):
                        campos.add(p)
        prods = set()
        if pcol:
            for v in grp[pcol].dropna().astype(str):
                p = v.strip()
                if p and p.lower() not in ("nan", "none", ""):
                    prods.add(p)
        campos_txt = ", ".join(sorted(campos)) if campos else "(campo no indicado)"
        info = campos_txt + (f"<br><i>{', '.join(sorted(prods))}</i>" if prods else "")
        xs += [d, d, None]
        ys += [0, ymax, None]
        cd += [info, info, info]
    return go.Scatter(
        x=xs, y=ys, mode="lines", name=name,
        line=dict(color=color, width=1.5, dash="dash"), connectgaps=False,
        customdata=cd,
        hovertemplate="<b>%{x|%d/%m}</b> · tratamiento<br>Campos: %{customdata}<extra></extra>",
    )


def _dec_disease_chart(risk_df, value_col, disease_name, today, treats_df, height=300, scale_max=160):
    """
    Crea gráfico Plotly estilo RIMpro para una enfermedad.
    Barras coloreadas por nivel de riesgo + lluvia como fondo + zona predicción.
    `scale_max` = tope del eje Y (160 por defecto: moteado/monilia llegan a 150). El
    Oídio pasa 105 porque su índice de favorabilidad NUNCA supera 100 → así el eje no
    desperdicia el tramo 100-160. Las franjas (Ligero 25 / Moderado 50 / Grave 100)
    no cambian.
    """
    import plotly.graph_objects as go

    dates  = risk_df["Fecha"].tolist()
    values = risk_df[value_col].fillna(0).tolist()
    lluvia = risk_df["Lluvia"].fillna(0).tolist()
    es_pred = risk_df["Es_prediccion"].tolist()
    _ymax = max(float(scale_max), max(values) * 1.05) if values else float(scale_max)

    fig = go.Figure()

    # Precipitación (fondo, eje secundario)
    fig.add_trace(go.Bar(
        x=dates, y=lluvia,
        name="Lluvia (mm)",
        marker_color="rgba(100,160,255,0.35)",
        yaxis="y2",
        hovertemplate="%{x|%d/%m}<br>Lluvia: %{y:.1f} mm<extra></extra>",
    ))

    # Zonas de gravedad de fondo (verde / amarillo / naranja / rojo)
    _zones = [
        (0,   25,  "rgba(44,160,44,0.10)"),    # verde   — sin/ligero
        (25,  50,  "rgba(245,197,24,0.14)"),   # amarillo — ligero
        (50,  100, "rgba(255,127,14,0.14)"),   # naranja  — moderado
        (100, _ymax, "rgba(214,39,40,0.14)"),  # rojo     — grave (hasta el tope del eje)
    ]
    for _lo, _hi, _col in _zones:
        fig.add_hrect(y0=_lo, y1=_hi, fillcolor=_col, line_width=0, layer="below")

    # (Aquí hubo una línea de «umbral de aviso» cuando la previsión se juzgaba con un
    #  listón más alto —140 en moteado—. Ya no hace falta: desde que build_risk_timeline
    #  corrige el sesgo de los días de predicción, el 100 significa lo mismo a los dos
    #  lados de «hoy» y la franja «Grave» vale para toda la gráfica.)

    # Curva de infección: línea suavizada (spline) rellena hasta cero. El relleno
    # deja ver las zonas de color del fondo → el área se "colorea" según la gravedad
    # que alcanza la curva. La línea se colorea según el pico del periodo.
    _peak_col = _dec_bar_color(max(values) if values else 0)
    fig.add_trace(go.Scatter(
        x=dates, y=values,
        name=disease_name,
        mode="lines",
        line=dict(shape="spline", smoothing=0.9, color=_peak_col, width=2.6),
        fill="tozeroy", fillcolor="rgba(120,120,120,0.10)",
        customdata=list(zip(
            risk_df["T_med"].fillna("?").tolist(),
            risk_df["HR_med"].fillna("?").tolist(),
            risk_df["Horas_mojadura"].tolist(),
            (risk_df[_evt_col].fillna("").tolist()
             if (_evt_col := {"Mills_valor": "Mills_evento",
                              "Monilia_valor": "Monilia_evento"}.get(value_col)) in risk_df.columns
             else [""] * len(risk_df)),
        )),
        hovertemplate=(
            "<b>%{x|%d/%m/%Y}</b><br>"
            f"Valor infección: %{{y:.0f}}<br>"
            "T media: %{customdata[0]}°C<br>"
            "HR media: %{customdata[1]}%<br>"
            "Horas mojadura (este día): %{customdata[2]}"
            "%{customdata[3]}<extra></extra>"
        ),
    ))

    # Etiquetas de umbral a la derecha
    fig.add_hline(y=100, line_dash="dash", line_color="rgba(214,39,40,0.5)", line_width=1,
                  annotation_text="Grave", annotation_position="right")
    fig.add_hline(y=50,  line_dash="dash", line_color="rgba(255,127,14,0.5)", line_width=1,
                  annotation_text="Moderado", annotation_position="right")
    fig.add_hline(y=25,  line_dash="dot",  line_color="rgba(204,187,0,0.5)", line_width=1,
                  annotation_text="Ligero", annotation_position="right")

    # Zona predicción
    pred_dates = risk_df[risk_df["Es_prediccion"]]["Fecha"]
    if not pred_dates.empty:
        x0_pred = pred_dates.min() - pd.Timedelta(hours=12)
        fig.add_vrect(
            x0=x0_pred,
            x1=risk_df["Fecha"].max() + pd.Timedelta(hours=12),
            fillcolor="rgba(180,210,255,0.12)", line_width=0,
        )
        fig.add_annotation(
            x=x0_pred, y=1, yref="paper",
            text="◀ real │ predicción ▶",
            showarrow=False, xanchor="left",
            font=dict(size=10, color="rgba(80,80,180,0.8)"),
            bgcolor="rgba(255,255,255,0.6)",
        )

    # Línea de hoy (solo si cae dentro del rango mostrado: en una campaña pasada
    # "hoy" queda fuera de la ventana y no debe estirar el eje ni pintarse).
    if not dates or (min(dates) <= today <= max(dates)):
        fig.add_vline(
            x=today,
            line_color="rgba(255,140,0,0.9)", line_width=2, line_dash="solid",
        )

    # Tratamientos — líneas verticales HOVERABLES (muestran los campos tratados ese día)
    _ymax_d = _ymax
    _tr_trace = _dec_treatment_lines_trace(
        go, treats_df, risk_df["Fecha"].min(), risk_df["Fecha"].max(), _ymax_d)
    if _tr_trace is not None:
        fig.add_trace(_tr_trace)

    fig.update_layout(
        height=height,
        margin=dict(l=0, r=60, t=10, b=30),
        barmode="overlay",
        showlegend=True,
        # Sin arrastre: que deslizar/clic-arrastrar sobre la gráfica NO la mueva
        # (en el móvil deja pasar el scroll de la página; en PC no la desplaza).
        dragmode=False,
        legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1, font_size=11),
        yaxis=dict(title="Valor de infección", range=[0, _ymax],
                   gridcolor="rgba(200,200,200,0.3)", fixedrange=True),
        yaxis2=dict(title="Lluvia (mm)", overlaying="y", side="right",
                    range=[0, max(max(lluvia)*4, 10) if lluvia else 10],
                    showgrid=False, tickfont_color="rgba(100,160,255,0.8)", fixedrange=True),
        # `tickmode="array"` con los ticks automáticos MÁS el último día: plotly
        # reparte las marcas cada 7 días y deja fuera el final de la previsión, que es
        # justo el dato que interesa saber — hasta dónde llega lo que estás mirando.
        xaxis=dict(tickformat="%d/%m", gridcolor="rgba(200,200,200,0.2)", fixedrange=True,
                   **({"tickmode": "array",
                       "tickvals": (list(pd.date_range(dates[0], dates[-1], freq="7D"))
                                    + [dates[-1]])}
                      if dates else {})),
        plot_bgcolor="rgba(255,255,255,1)",
        paper_bgcolor="rgba(0,0,0,0)",
        bargap=0.1,
    )
    return fig


def _dec_carpocapsa_chart(risk_df, today, biofix_df, traps_df, treats_carpo_df, base_temp, upper_temp, height=320, days_back=45, history_df=None):
    """Gráfico de DD acumulados desde biofix + capturas + tratamientos."""
    import plotly.graph_objects as go

    # Determinar biofix del año en curso
    biofix_date = None
    current_year = today.year
    if biofix_df is not None and not biofix_df.empty and "Fecha biofix" in biofix_df.columns:
        bf_all_dates = pd.to_datetime(biofix_df["Fecha biofix"], errors="coerce").dropna()
        if not bf_all_dates.empty:
            # 1. Preferir fechas cuyo año coincide con el año actual
            bf_current = bf_all_dates[bf_all_dates.dt.year == current_year]
            if not bf_current.empty:
                biofix_date = bf_current.min()
            else:
                # 2. Sin biofix del año actual → proyectar la fecha más reciente al año en curso
                last_bf = bf_all_dates.max()
                candidate = last_bf.replace(year=current_year)
                # Usar sólo si ya ha pasado; si es futura (raro), usar año anterior
                biofix_date = candidate if candidate <= pd.Timestamp(today) else last_bf.replace(year=current_year - 1)

    # Construir DD desde biofix usando todo el histórico si está disponible
    # (así DD acumulado es correcto aunque sólo mostremos la ventana reciente)
    if biofix_date is not None and history_df is not None and not history_df.empty:
        _h = history_df.copy()
        _h["fecha_hora"] = pd.to_datetime(_h["fecha_hora"])
        _h["_fecha"] = _h["fecha_hora"].dt.date
        _h["temp_media"] = pd.to_numeric(_h["temp_media"], errors="coerce")
        _h_daily = (
            _h[_h["fecha_hora"] >= pd.Timestamp(biofix_date)]
            .groupby("_fecha")["temp_media"].mean()
            .reset_index()
        )
        _h_daily["DD_dia_full"] = (_h_daily["temp_media"].clip(upper=float(upper_temp)) - base_temp).clip(lower=0)
        _h_daily["Fecha"] = pd.to_datetime(_h_daily["_fecha"])
        _h_daily["DD_acum_full"] = _h_daily["DD_dia_full"].cumsum().round(1)
        # Merge the full cumulative DD back into risk_df by date
        _merge = risk_df.merge(
            _h_daily[["Fecha", "DD_acum_full"]],
            on="Fecha", how="left"
        )
        # For forecast dates (not in history), extend cumulation
        last_dd = _merge["DD_acum_full"].dropna().iloc[-1] if not _merge["DD_acum_full"].dropna().empty else 0.0
        for i in _merge.index:
            if pd.isna(_merge.at[i, "DD_acum_full"]):
                # Fechas ANTERIORES al biofix → 0 (aún no hay DD; NO arrastrar el acumulado
                # final hacia atrás, que daba valores altísimos antes del biofix y rompía la
                # interpolación de las capturas). Fechas de PREDICCIÓN (tras el último real)
                # → extender el acumulado.
                if biofix_date is not None and _merge.at[i, "Fecha"] < biofix_date:
                    _merge.at[i, "DD_acum_full"] = 0.0
                else:
                    last_dd = last_dd + _merge.at[i, "DD_dia"]
                    _merge.at[i, "DD_acum_full"] = round(last_dd, 1)
        plot_df = _merge.copy()
        plot_df["DD_acumulado"] = plot_df["DD_acum_full"]
    else:
        plot_df = risk_df.copy()
        if biofix_date is not None:
            plot_df = plot_df[plot_df["Fecha"] >= biofix_date].copy()
            if not plot_df.empty:
                plot_df["DD_acumulado"] = plot_df["DD_dia"].cumsum().round(1)

    if plot_df.empty:
        plot_df = risk_df.copy()

    # Ventana de visualización: sólo mostrar los últimos days_back días + predicción
    display_start = today - pd.Timedelta(days=int(days_back))
    plot_df_display = plot_df[plot_df["Fecha"] >= display_start].copy()
    if plot_df_display.empty:
        plot_df_display = plot_df.copy()

    dates     = plot_df_display["Fecha"].tolist()
    dd_acum   = plot_df_display["DD_acumulado"].tolist()
    dd_dia    = plot_df_display["DD_dia"].tolist()
    es_pred   = plot_df_display["Es_prediccion"].tolist()
    lluvia    = plot_df_display["Lluvia"].fillna(0).tolist()

    fig = go.Figure()

    # ── Bandas de eclosión (1–99 %), RECORTADAS A LA CURVA ────────────────────
    # No es una franja horizontal que cruza el gráfico: se rellena solo el área
    # BAJO la curva de DD que cae dentro del periodo de eclosión de cada
    # generación. Así el relleno dibuja la fase real por la que pasó el campo, y
    # se ve de un vistazo cuánto tiempo estuvo dentro de cada ventana.
    # Se pintan ANTES que la curva y las capturas para quedar por debajo: plotly
    # respeta el orden de los traces como z-order.
    for _lo, _hi, _blbl, _bcol in CARPOCAPSA_HATCH_BANDS:
        _yb, _yt = [], []          # borde inferior y superior del relleno
        for _v in dd_acum:
            # Solo mientras la curva esté DENTRO de la banda. Si se sigue pintando
            # una vez superado el techo, el relleno se queda plano hasta el borde
            # derecho y vuelve a parecer una franja horizontal.
            _ok = (_v is not None and not (isinstance(_v, float) and np.isnan(_v))
                   and _lo < _v <= _hi)
            _yb.append(_lo if _ok else None)
            _yt.append(_v if _ok else None)
        if not any(v is not None for v in _yt):
            continue               # la curva nunca llega a esta banda
        fig.add_trace(go.Scatter(
            x=dates, y=_yb, mode="lines", line=dict(width=0),
            showlegend=False, hoverinfo="skip"))
        fig.add_trace(go.Scatter(
            x=dates, y=_yt, mode="lines", line=dict(width=0),
            fill="tonexty", fillcolor=_bcol,
            showlegend=False, hoverinfo="skip"))
        # Etiqueta DENTRO del relleno, centrada en el tramo cubierto. Se coloca a
        # media altura de la zona rellena en ese punto, no en el borde.
        _idx = [i for i, v in enumerate(_yt) if v is not None]
        _mid = _idx[len(_idx) // 2]
        _alto = _yt[_mid] - _lo
        if _alto > 40:             # si la franja es muy fina la etiqueta no cabe
            fig.add_annotation(
                x=dates[_mid], y=_lo + _alto / 2, text=_blbl, showarrow=False,
                font=dict(size=9, color="#4a4a4a"), opacity=0.85)

    # (La traza "DD diarios" y su eje derecho (DD/día 0-70) se quitaron: metían ruido y
    #  su escala confundía —parecía que se acumulaban 70 DD/día—; solo interesa el DD acumulado.)

    # DD acumulados — histórico
    hist_idx = [i for i, p in enumerate(es_pred) if not p]
    pred_idx = [i for i, p in enumerate(es_pred) if p]

    if hist_idx:
        fig.add_trace(go.Scatter(
            x=[dates[i] for i in hist_idx],
            y=[dd_acum[i] for i in hist_idx],
            mode="lines",
            name="DD acumulados (real)",
            line=dict(color="#d62728", width=2.5),
            fill="tozeroy",
            fillcolor="rgba(214,39,40,0.12)",
            hovertemplate="%{x|%d/%m}<br>DD acum: %{y:.0f}<extra></extra>",
        ))

    if pred_idx:
        # Conectar con el último punto del histórico
        connect_i = hist_idx[-1] if hist_idx else pred_idx[0]
        x_pred = [dates[connect_i]] + [dates[i] for i in pred_idx]
        y_pred = [dd_acum[connect_i]] + [dd_acum[i] for i in pred_idx]
        fig.add_trace(go.Scatter(
            x=x_pred, y=y_pred,
            mode="lines",
            name="DD acumulados (predicción)",
            line=dict(color="#d62728", width=2, dash="dot"),
            fill="tozeroy",
            fillcolor="rgba(214,39,40,0.05)",
            hovertemplate="%{x|%d/%m}<br>DD acum (prev): %{y:.0f}<extra></extra>",
        ))

    # Umbrales de tratamiento. El eje llega SIEMPRE al menos hasta el último umbral de
    # 2ª generación (750) para que se vean las mismas líneas que en el item Carpocapsa,
    # aunque los DD del año aún no hayan llegado ahí. Los hitos de 3ª gen (1230/1370)
    # NO estiran el eje: solo aparecen si los DD reales se acercan — si no, aplastarían
    # la curva contra el suelo durante toda la primavera.
    max_dd  = max(dd_acum) if dd_acum else 400
    _top_gen = max((t for t, _ in CARPOCAPSA_GEN_DD if t <= 750), default=750)
    ymax    = max(max_dd * 1.15, _top_gen * 1.08, 400)
    _gen_colors = ["#2ca02c", "#ff7f0e", "#d62728", "#9467bd", "#8c564b", "#e377c2"]
    for (umbral, _lbl), color in zip(CARPOCAPSA_GEN_DD, _gen_colors):
        # Etiqueta corta para que quepa entera a la derecha (antes se cortaba el nº).
        _short = carpo_gen_label_short(_lbl)
        label = f"{_short} ({umbral} DD)"
        if umbral <= ymax * 1.2:
            fig.add_hline(y=umbral, line_dash="dash", line_color=color, line_width=1, opacity=0.7,
                          annotation_text=label, annotation_position="right",
                          annotation_font_size=10)

    # Capturas de trampas (detección flexible de columnas: la tabla real usa
    # "Fecha" y "Capturas machos", no "Fecha_dt"/"Capturas"). Se AGREGAN por fecha
    # en toda la finca → un círculo por lectura, con el total de capturas.
    if traps_df is not None and not traps_df.empty:
        tf = traps_df.copy()
        _dcol = next((c for c in ["Fecha_dt", "Fecha"] if c in tf.columns), None)
        _ccol = next((c for c in ["Capturas", "Capturas machos"] if c in tf.columns), None)
        if _dcol and _ccol:
            tf["_fdt"] = pd.to_datetime(tf[_dcol], errors="coerce")
            tf = tf.dropna(subset=["_fdt"])
            if not plot_df_display.empty:
                tf = tf[(tf["_fdt"] >= plot_df_display["Fecha"].min()) &
                        (tf["_fdt"] <= plot_df_display["Fecha"].max())]
            if not tf.empty:
                tf["_cap"] = pd.to_numeric(tf[_ccol], errors="coerce").fillna(0)
                tg_all = tf.groupby(tf["_fdt"].dt.normalize(), as_index=False)["_cap"].sum()
                # DD acumulado en la fecha de CADA lectura, por lookup exacto/cercano (el
                # np.interp anterior devolvía siempre el último valor → todas a la misma altura).
                _ddser = (plot_df_display.assign(
                              _d=pd.to_datetime(plot_df_display["Fecha"]).dt.normalize())
                          .drop_duplicates("_d").set_index("_d")["DD_acumulado"].sort_index())
                # Lecturas CON capturas: círculo azul (tamaño por nº) + número.
                tg = tg_all[tg_all["_cap"] > 0]
                if not tg.empty:
                    _cap_d = pd.to_datetime(tg["_fdt"]).dt.normalize()
                    dd_interp = _ddser.reindex(_cap_d, method="nearest").fillna(0).to_numpy()
                    fig.add_trace(go.Scatter(
                        x=tg["_fdt"].tolist(),
                        y=dd_interp.tolist(),
                        mode="markers+text",
                        name="Capturas trampa",
                        marker=dict(
                            size=[max(8, min(c * 1.5, 30)) for c in tg["_cap"]],
                            color="rgba(0,120,200,0.75)",
                            symbol="circle",
                            line=dict(color="white", width=1),
                        ),
                        text=tg["_cap"].astype(int).astype(str),
                        # arriba-derecha: si coincide con una línea de tratamiento (vertical
                        # en la x de la captura), el número no queda tapado por ella.
                        textposition="top right",
                        textfont=dict(size=10, color="rgba(0,80,160,1)"),
                        customdata=tg["_cap"].tolist(),
                        hovertemplate="%{x|%d/%m}<br>Capturas: %{customdata}<br>DD: %{y:.0f}<extra></extra>",
                    ))
                # Lecturas SIN capturas (0): marcador pequeño hueco gris → deja claro que la
                # trampa SÍ se revisó ese día aunque no cayera nada (antes se ocultaban y el
                # hueco entre capturas parecía "no se hizo lectura").
                tg0 = tg_all[tg_all["_cap"] <= 0]
                if not tg0.empty:
                    _cd0 = pd.to_datetime(tg0["_fdt"]).dt.normalize()
                    _dd0 = _ddser.reindex(_cd0, method="nearest").fillna(0).to_numpy()
                    fig.add_trace(go.Scatter(
                        x=tg0["_fdt"].tolist(),
                        y=_dd0.tolist(),
                        mode="markers",
                        name="Lectura sin capturas (0)",
                        marker=dict(size=8, color="rgba(105,105,105,0.9)", symbol="circle",
                                    line=dict(color="white", width=1.4)),
                        hovertemplate="%{x|%d/%m}<br>Lectura de trampa: 0 capturas<br>DD: %{y:.0f}<extra></extra>",
                    ))

    # Zona predicción
    pred_dates_df = plot_df_display[plot_df_display["Es_prediccion"]]["Fecha"]
    if not pred_dates_df.empty:
        fig.add_vrect(
            x0=pred_dates_df.min() - pd.Timedelta(hours=12),
            x1=plot_df_display["Fecha"].max() + pd.Timedelta(hours=12),
            fillcolor="rgba(180,210,255,0.12)", line_width=0,
        )

    # Línea de hoy
    fig.add_vline(x=today, line_color="rgba(255,140,0,0.9)", line_width=2)

    # Biofix marker — sólo si cae dentro de la ventana visible
    # (si está fuera, add_vline forzaría el eje X a extenderse hasta esa fecha)
    if biofix_date is not None:
        if biofix_date >= display_start:
            fig.add_vline(x=biofix_date, line_color="rgba(0,160,0,0.8)", line_width=2, line_dash="dash")
            # La etiqueta va a media altura de su línea, NO arriba del todo: el cuadro
            # de "próxima eclosión" ocupa esa esquina y se solapaban. La línea del
            # biofix es vertical, así que la etiqueta se lee igual a cualquier altura,
            # y a media altura la curva aún va baja (acaba de arrancar) — queda libre.
            fig.add_annotation(
                x=biofix_date, y=0.62, yref="paper",
                text=f"Biofix {biofix_date.strftime('%d/%m')}",
                showarrow=False, xanchor="left", yanchor="middle", xshift=3,
                font=dict(color="green", size=11),
                bgcolor="rgba(255,255,255,0.75)",
            )
        else:
            # Biofix fuera de la ventana: mostrar DD totales en subtítulo
            total_dd = dd_acum[-1] if dd_acum else 0
            fig.add_annotation(
                x=0, y=1.06, xref="paper", yref="paper",
                text=f"Biofix: {biofix_date.strftime('%d/%m/%Y')} · DD acumulados desde biofix: {total_dd:.0f}",
                showarrow=False, xanchor="left",
                font=dict(color="green", size=11),
                bgcolor="rgba(255,255,255,0.75)",
            )

    # Tratamientos carpocapsa — líneas verticales HOVERABLES (campos tratados ese día)
    if not plot_df_display.empty:
        _tr_carpo = _dec_treatment_lines_trace(
            go, treats_carpo_df, plot_df_display["Fecha"].min(),
            plot_df_display["Fecha"].max(), ymax, name="Tratamiento carpo.")
        if _tr_carpo is not None:
            fig.add_trace(_tr_carpo)

    # ── Proyección: ¿cuándo se cruza el próximo umbral de generación? ─────────
    # La curva DD ya se prolonga con la previsión de Sencrop (tramo punteado), pero
    # el siguiente umbral (p. ej. 2ª gen) suele caer SEMANAS después, fuera de esa
    # previsión corta. Estimamos la fecha extrapolando el DD acumulado actual al
    # RITMO de DD/día de los últimos días reales. Es una estimación (temperaturas
    # futuras reales mandan) → se rotula con «≈» y el ritmo usado, sin fingir certeza.
    try:
        if (biofix_date is not None and not plot_df.empty
                and "DD_acumulado" in plot_df.columns and "DD_dia" in plot_df.columns):
            _pf = plot_df.dropna(subset=["DD_acumulado"]).sort_values("Fecha")
            _real = _pf[~_pf["Es_prediccion"]] if "Es_prediccion" in _pf.columns else _pf
            if not _real.empty:
                dd_now   = float(_real["DD_acumulado"].iloc[-1])
                last_real = pd.Timestamp(_real["Fecha"].iloc[-1])
                rate = float(pd.to_numeric(_real["DD_dia"].tail(10), errors="coerce")
                             .dropna().mean())
                _proj = []
                if rate and rate > 0.3:
                    for _um, _lb in CARPOCAPSA_GEN_DD:
                        if _um > dd_now:
                            _days = (_um - dd_now) / rate
                            if _days <= 120:   # no proyectar más de ~4 meses
                                _est = last_real + pd.Timedelta(days=float(_days))
                                _sh = carpo_gen_label_short(_lb)
                                _proj.append(f"{_sh} ({int(_um)} DD) ≈ <b>{_est.strftime('%d/%m')}</b>")
                if _proj:
                    _proj_txt = (f"📅 Próxima eclosión estimada (~{rate:.1f} DD/día):<br>"
                                 + "<br>".join(_proj[:2]))
                    fig.add_annotation(
                        x=0.01, y=0.97, xref="paper", yref="paper",
                        text=_proj_txt, showarrow=False,
                        xanchor="left", yanchor="top", align="left",
                        font=dict(size=10, color="#4b2e83"),
                        bgcolor="rgba(255,255,255,0.82)",
                        bordercolor="rgba(120,80,160,0.5)", borderwidth=1, borderpad=4,
                    )
    except Exception:
        pass

    # Calcular límites explícitos del eje X para que Plotly no los amplíe
    # aunque algún add_vline/add_annotation caiga fuera de los datos
    if not plot_df_display.empty:
        _x_end = plot_df_display["Fecha"].max() + pd.Timedelta(hours=12)
    else:
        _x_end = today + pd.Timedelta(days=7)
    _x_start = display_start - pd.Timedelta(hours=12)

    fig.update_layout(
        height=height,
        margin=dict(l=0, r=150, t=30, b=30),   # margen derecho amplio: etiquetas de generación legibles
        barmode="overlay",
        showlegend=True,
        dragmode=False,   # sin arrastre: deslizar sobre la gráfica no la mueve
        legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1, font_size=11),
        yaxis=dict(title="DD acumulados", range=[0, ymax], gridcolor="rgba(200,200,200,0.3)", fixedrange=True),
        xaxis=dict(
            tickformat="%d/%m",
            gridcolor="rgba(200,200,200,0.2)",
            range=[_x_start, _x_end],   # ← fija el rango; evita expansión por biofix lejano
            fixedrange=True,
        ),
        plot_bgcolor="rgba(250,250,255,1)",
        paper_bgcolor="rgba(0,0,0,0)",
        bargap=0.1,
    )
    return fig


